INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '032-08'), 'GER', '{"alarmas": "Referencia a segundo nivel si el niño tiene edad menor de 3 meses, bronquiolitis moderada o grave, saturación de oxígeno <90%, rechazo o intolerancia a la vía oral (menos del 50% de la ingesta habitual), deshidratación, letargia, presencia o historia de apneas, taquipnea mayor a 70 respiraciones por minuto, dificultad respiratoria moderada o grave, diagnóstico dudoso, comorbilidades asociadas (cardiopatías, enfermedad pulmonar crónica, inmunodeficiencias), padres adolescentes o incapacidad familiar para cuidado adecuado, antecedente de hermano fallecido por enfermedad pulmonar, no mejoría clínica con tratamiento inicial, factores socioeconómicos o geográficos que dificulten el seguimiento, o deterioro del estado general durante seguimiento domiciliario.", "prevencion": "Promover lactancia materna exclusiva por al menos 6 meses para protección contra infecciones respiratorias. Evitar exposición a humo de tabaco y ambientes contaminados. Prevenir hacinamiento y acudir a guarderías solo después de la convalecencia. Mantener medidas de higiene como lavado frecuente de manos y uso de geles alcohólicos en cuidadores. Identificar y controlar factores de riesgo como prematurez y enfermedades crónicas. Fomentar ambiente saludable y evitar la exposición a lugares concurridos durante la temporada epidémica.", "diagnostico": "Diagnóstico clínico en niños menores de 2 años con rinorrea, tos, dificultad respiratoria, sibilancias o estertores crepitantes finos. Uso de escala clínica validada para clasificar la gravedad (leve, moderada, grave). No se recomienda realizar estudios radiográficos ni de laboratorio de rutina, salvo en casos con diagnóstico dudoso o sospecha de complicaciones. La prueba rápida para virus sincitial respiratorio (VSR) puede apoyar el diagnóstico y manejo. Identificar factores de riesgo para bronquiolitis grave: prematurez, cardiopatías congénitas, enfermedad pulmonar crónica, hipertensión pulmonar, inmunodeficiencia, edad menor a 3 meses, bajo peso al nacer y antecedentes clínicos relevantes.", "seguimiento": "Realizar revaloración clínica entre 24 y 48 horas después del diagnóstico inicial, especialmente en menores de 12 meses, para evaluar función respiratoria y evolución. Seguir de cerca a pacientes con factores de riesgo como edad menor a 2 meses, sexo masculino o antecedentes de hospitalización. En manejo domiciliario, instruir a padres sobre signos de alarma y cuidados. Duración promedio de recuperación es de 12 días. Aconsejar contacto inmediato con servicios de urgencias si aparecen signos de alarma o deterioro clínico.", "tratamiento": "Manejo no farmacológico que incluye hidratación oral con líquidos en tomas pequeñas y frecuentes, aseo nasal con solución salina o agua hervida tibia, mantener al niño en posición semisentada y evitar exposición a humo de tabaco y lugares concurridos. Oxigenoterapia si saturación <90% para mantener saturación entre 90-94% vía puntas nasales o nebulización (3-5-10 L/min). En pacientes con antecedentes de atopia o asma, nebulización con una sola dosis de salbutamol 100-200 mcg cada 4-6 horas; evaluar respuesta para continuar. Si hay indicación de dosis única, administrar adrenalina nebulizada 0.5 mg/kg disuelta en 2 ml suero fisiológico (dosis única en primer nivel). No usar antibióticos, corticoides inhalados, inhibidores de leucotrienos, antihistamínicos ni descongestionantes. Paracetamol 10-15 mg/kg/dosis cada 6-8 horas hasta 3 días para fiebre >38°C."}'::jsonb, false, 25731, '2026-11-25 23:40:21.711+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '032-08'), 'GRR', E'{"alarmas": "Referir a segundo nivel si: edad menor de 3 meses, prematurez, bronquiolitis moderada o grave, saturación <90%, rechazo o intolerancia oral (menos del 50% de ingesta habitual), deshidratación, letargia, apneas, taquipnea para edad, dificultad respiratoria moderada/grave, diagnóstico dudoso, comorbilidad, padres con dificultad para cuidado, antecedentes familiares de muerte por enfermedad pulmonar, falta de mejoría tras tratamiento, factores socioeconómicos o geográficos adversos y incapacidad familiar para evaluar gravedad.", "prevencion": "Promover lactancia materna exclusiva por al menos 6 meses. Evitar hacinamiento en domicilio y quedarse en casa durante episodio infeccioso. Evitar exposición al humo de tabaco, lugares concurridos y contacto con enfermos de vías respiratorias. Lavarse las manos regularmente con agua y jabón o usar alcohol gel antes y después de tocar al niño. Mantener ambiente tranquilo y evitar arropamiento excesivo.", "diagnostico": "El diagnóstico es clínico, basado en historia y examen físico en niños menores de 2 años con rinorrea, tos, dificultad respiratoria, sibilancias o estertores crepitantes. No se recomienda realizar estudios radiológicos ni de laboratorio de forma rutinaria. La escala clínica de gravedad ayuda a clasificar bronquiolitis en leve (1-3 puntos), moderada (4-7) o grave (8-14). Prueba rápida para identificar agente causal puede considerarse.", "seguimiento": "Revaloración clínica entre 24 y 48 horas para vigilar función respiratoria y condiciones generales, especialmente en menores de 12 meses o con predictores de empeoramiento (menores de 2 meses, sexo masculino, antecedentes de hospitalización). Explicar signos de alarma a padres para acudir a urgencias ante deterioro. Seguimiento domiciliario en niños con buenas condiciones: estado general bueno, gravedad <3, saturación >94%, tolerancia adecuada vía oral.", "tratamiento": "No usar corticoesteroides, leucotrienos, antihistamínicos, descongestionantes ni antibióticos. Paracetamol para fiebre ≥38°C a 10-15 mg/kg/dosis cada 6-8 horas, máximo 60 mg/kg/día por máximo 3 días. En pacientes sin atopia ni asma, no se recomienda nebulización de solución salina hipertónica en primer nivel; en caso de indicación, referir. En antecedentes de asma o atopia, aplicar una dosis única de salbutamol inhalado (1-2 disparos) o nebulizado, evaluar respuesta y decidir continuar ambulatorio o referir. O2 suplementario si saturación <90% para mantener entre 90-94%, con flujo 3-5-10 l/min por puntas nasales o nebulización con FiO2 >30%.", "texto_completo": "Guía de Referencia Rápida \\nCatálogo Maestro de Guías de Práctica Clínica: IMSS-032-08 \\nGUÍA DE PRÁCTICA CLÍNICA\\n \\nGPC\\n \\n \\n \\nDiagnóstico y Tratamiento de\\n \\nB\\nRONQUIOLITIS \\nA\\nGUDA\\n \\nEn niñas/niños y en el Primer \\nNivel de Atención \\n \\nActualización \\n2015 \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nDurango 289- 1A Colonia Roma \\nDelegación Cuauhtémoc, 06700 México, DF. \\nPágina Web: www.imss.gob.mx \\n \\nPublicado por Instituto Mexicano del Seguro Social \\n© Copyright Instituto Mexicano del Seguro Social “Derechos Reservados”. Ley Federal de Derecho de Autor \\n \\nEditor General \\nCoordinación Técnica de Excelencia Clínica \\nCoordinación de Unidades Médicas de Alta Especialidad \\n2015 \\n \\nLa guía  de  referencia  rápida tiene  como  objetivo  proporcionar  al  usuario  las recomendaciones  clave de  la  guía \\nDiagnóstico  y  Tratamiento  de  Bronquiolitis  Aguda  En  niñas/niños  y en  el  Primer  Nivel  de  Atención, \\nseleccionadas con base a su impacto en salud por el grupo desarrollador, las cuales pueden variar en función  de la \\nintervención de que se trate, así como del contexto regional o local en el ámbito de su aplicación. \\n \\nPara mayor información, se sugiere consultar la guía en su versión extensa de “Evidencias y Recomendaciones” en el \\nCatálogo Maestro de Guías de Práctica Clínica, la cual puede ser descargada de Internet en: \\nhttp://www.cenetec.salud.gob.mx/interior/catalogoMaestroGPC.html\\n \\n \\nISBN 978-607-7790-84-6\\n \\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n \\n \\n1. Diagramas de Flujo \\n \\nAlgoritmo 1. Diagnóstico y Tratamiento de la Bronquiolitis Aguda \\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\n \\n2. Prevención primaria \\n \\nPROMOCIÓN A LA SALUD \\n \\nRecomendación Clave \\nGR*\\n \\nLos médicos deben alentar la lactancia materna exclusiva durante al menos 6 meses \\npara  disminuir  la  probabilidad  de  infecciones  de  las  vías  respiratorias  incluida  la \\nbronquiolitis aguda. \\nB  \\nmoderado \\nEvitar el hacinamiento en el domicilio de el/la niño/a. \\nEn  pacientes  con  sospecha  de  bronquiolitis    se  recomienda  permancer  en  casa \\ndurante el evento infeccioso y acudir a guarderías hasta terminar convalescencia \\nC \\n \\n \\nDETECCIÓN \\n \\nRecomendación Clave\\n \\nGR*\\n \\n \\nIdentificar los factores de riesgo relacionados a bronquiolitis grave desde la primera \\nconsulta, como son: \\n El/la  niño/a con  antecedentes  de  prematurez y bajo  peso  al  nacer \\n<2,500gramos. \\n Cardiopatías congénitas. \\n Enfermedad pulmonar crónica del prematuro. \\n El/la niño/a procedentes de familias con recursos bajos; particularmente durante \\nla época de invierno y principios de primavera. \\nC \\nB \\nmoderado \\n \\nEl diagnóstico de la  Bronquiolitis es clínico, la prueba  rápida permite identificar  el \\nagente causal. \\nA fuerte \\nC \\n \\n \\n \\n \\n \\n \\n3. Prevención Secundaria \\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\nDIAGNÓSTICO \\n \\nRecomendación Clave\\n \\nGR*\\n \\nDurante la época invernal, considerar la posibilidad de bronquiolitis en el/la niño/a \\nmenor de dos años con síntomas respiratorios. \\nD \\n \\n \\nSe recomienda sospechar bronquiolitis en el/la niño/a menor de 2 años con: \\n Rinorrea. \\n Tos. \\n Dificultad respiratoria. \\n Sibilancias o estertores crepitantes finos. \\n Hiperinsuflación y dificultad respiratoria. \\n \\nA fuerte \\n \\nLa  fiebre  no  es  síntoma  cardinal  de  la  bronquiolitis,  su  presencia  o  ausencia  no \\ndescarta la posibilidad de infección. \\nC \\n \\nCuando  la  temperatura  es  mayor  a 39º  C  (axilar),  se  recomienda  buscar \\ncomplicaciones u otras posibles enfermedades como diagnósticos diferenciales. \\nC \\n \\n \\nRealizar  una  valoración  clínica  completa  en  todo  paciente  con  diagnóstico  de \\nbronquiolitis, utilizando la escala validada para determinar la gravedad de la \\nenfermedad y definir la modalidad de tratamiento a otorgarse, en el primer nivel de \\natención (Cuadro 1). \\nC \\n \\n \\nEn pacientes con bronquiolitis que cursan con temperatura axilar mayor de 39° C se \\ndebe investigar  complicaciones  como  otitis media,  neumonía  bacteriana  o  buscar \\notro foco infeccioso como infección de vías urinarias. \\n \\nPunto de \\nBuena \\nPráctica \\nSe recomienda no realizar, de manera rutinaria, radiografía de tórax para establecer \\nel diagnóstico de bronquiolitis aguda. \\nA \\n \\nSe recomienda establecer el diagnóstico de bronquiolitis aguda en el/la niño/a menor \\nde 2 años con base en la historia clínica y los datos clínicos recuperados durante la \\nexploración física \\n \\nA \\nD \\n \\nSe sugiere no realizar ningún estudio para confirmar el diagnóstico de bronquiolitis en \\npacientes ambulatorios. \\nA \\nD \\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\nEl diagnóstico de la bronquiolitis es clínico,  se basa en la historia clínica y el examen \\nfísico, se recomienda no realizar estudios radiológicos ni sanguíneos, a menos que el \\ndiagnóstico no sea claro o se sospeche otro proceso infeccioso de vías aéreas bajas u \\notras entidades nosológicas. \\n \\nA \\nC \\nD \\n \\n \\nTRATAMIENTO FARMACOLÓGICO \\n \\nRecomendación Clave\\n \\nGR*\\n \\n \\nAntes de indicar nebulizacion de solución salina hipertónica al 3% debe descartarse \\nhistoria de atopia / asma.  \\n \\nA \\nEn caso de considerar aplicación de nebulización de solución salina hipertónica al 3% \\nenviar a siguiente nivel de atención. \\nA \\nEn pacientes con antecedentes de atopia, asma o alergia, se recomienda aplicar una \\nsola dosis de salbutamol en aerosol (por medio de el [1-2 disparos], si se cuenta con \\nel recurso) o por nebulizaciones. \\nA \\n \\nDespués de la aplicación de salbutamol, se recomienda examinar la respuesta clínica \\ncon base en la disminución de las sibilancias y cambios en la calificación de la escala \\nde gravedad, para determinar si el/la niño/a con bronquiolitis puede continuar con el \\ntratamiento en su domicilio. \\n \\nB \\nSe  recomienda  no  utilizar corticoesteroides, inhibidores  de  leucotrienos \\n(Montelukast)  antihistamínicos  o  descongestionantes  (sistémicos,  orales  o \\ninhalados),  vasoconstrictores  nasales  ni antibióticos  en  el  tratamiento de el/la \\nniño/a con bronquiolitis. \\nA \\nB, C, D \\n \\n \\nPuede prescribir  paracetamol  para  el  control  de  la  fiebre  cuando  la  temperatura \\n(axilar) sea igual o mayor a 38° C en el/la niño/a con bronquiolitis; a razón de 10 a \\n15 miligramos por kilogramos de peso por dosis (sin exceder 60 mg por kg al día) \\ncada 6 a 8 horas en un tiempo no mayor de 3 días. \\n. \\n \\nPunto de \\nBuena \\nPráctica. \\nLa Ribavirina no está recomendada para el tratamiento de la bronquiolitis aguda en \\nel/la niño/a. \\nB \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\nEn saturaciones de oxigeno menor de 90%  administrar oxígeno por medio puntas \\nnasales (3 a 5-10 l/min) o nebulizador ( FiO\\n2\\n >30%) para mantener saturación entre  \\n90 y 94%, estabilizar al paciente y evaluar envío al siguiente nivel de atención, \\nadministrando una dosis de adrenalina inhalada o salbutamol inhalado. \\n \\nA \\nC \\n \\n \\nTRATAMIENTO NO FARMACOLÓGICO \\n \\nRecomendación Clave\\n \\nGR\\n \\n \\nSe recomienda indicar a los padres (o tutores) las siguientes medidas para el manejo \\nambulatorio de el/la niño/a con bronquiolitis leve: \\n Suministrar líquidos en tomas pequeñas y frecuentes. \\n Ofrecer alimentos de manera habitual. \\n Aseo  nasal  con  agua  hervida  (tibia) o  solución  salina para  evitar  la \\nobstrucción.  \\n Colocar \\nel/la niño/a\\n en posición semisentado. \\n Evitar la exposición al humo del tabaco. \\n Evitar lugares concurridos. \\n Mantener \\nel/la  niño/a\\n en  un  ambiente  tranquilo;  evitando  el  arropamiento \\nexcesivo. \\n Tomar la temperatura varias veces al día. \\n \\nS, E \\nC \\nSe  recomienda  instruir  a  los  padres  (o  tutores)  sobre  los  signos  de  alarma  (ver \\nrecomendaciones de bronquiolitis para padres y cuidadores). \\nPunto de \\nBuena \\nPráctica \\n \\nCRITERIOS DE REFERENCIA \\n \\nRecomendación Clave\\n \\nGR*\\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\nConsiderar criterios de referencia al segundo nivel (o urgencias, de acuerdo  a las \\ncondiciones del caso) para atención integral y admisión hospitalaria: \\n Prematurez,  \\n Edad (<3 meses) \\n Gravedad de la enfermedad (Apartado 5.3) \\n Bronquiolitis moderada o grave (Cuadro 1 apartado 5.3) \\n Saturación <90% \\n Rechazo de alimento o intolerancia de la vía oral (ingesta aproximada inferior \\nal 50% de lo habitual) \\n Deshidratación \\n Letargia \\n Historia o presencia de apneas \\n Taquipnea para su edad \\n Dificultad respiratoria moderada o grave  \\n Diagnóstico dudoso. \\n Comorbilidad asociada \\n Padres adolescentes  \\n Dificultad de la familia para cuidar a el/la niño/a \\n Antecedente de un hermano muerto por enfermedad pulmonar (<5 años) \\n Sin mejoría clínica posterior al inicio del tratamiento \\n Situación  socioeconómica del  entorno,  factores  geográficos  y  dificultad  de \\ntransporte \\n Capacidad limitada de los padres o cuidadores para evaluar la gravedad de \\nel/la niño/a. \\n \\nC \\nD \\n \\nVIGILANCIA Y SEGUIMIENTO \\n \\nRecomendación Clave \\nGR\\n \\n \\nSe  recomienda  realizar  una  revaloración  a las  24  o  48  horas  para  determinar  la \\nfunción respiratoria y las condiciones generales de el/la niño/a. Particularmente, en \\nniñas/niños menores de 12 meses de edad que presentaron síntomas de infección en \\nlas vías respiratorias altas durante la época epidémica de la bronquiolitis. \\n \\nD \\n \\n \\nSe recomienda realizar seguimiento de el/la niño/a con bronquiolitis a las 24 o 48 \\nhoras  de  la  consulta  inicial,  teniendo  en  cuenta  especialmente  a  aquellos  con \\npredictores de empeoramiento en su evolución como son: \\n Menores de 2 meses \\n Sexo masculino y \\n Antecedentes de hospitalización \\nSe  sugiere  llevar  seguimiento  estrecho  en el/la  niño/a con  bronquiolitis  a las  48 \\nhoras y al final del padecimiento, sobre todo en el grupo de menores de 12 meses de \\nC \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\nedad. \\n \\n \\nSi durante el seguimiento en casa, hay deterioro del estado general o signos de \\nalarma (dificultad respiratoria, cianosis, apnea, rechazo al alimento o vómito), se \\nrecomienda acudir de inmediato al servicio de urgencias. \\n \\nC \\nD \\n \\nSe sugiere llevar  a  cabo  seguimiento  en  su  domicilio,  explicando  a los  padres  la \\nenfermedad  y  los  signos  de  alarma,  en  aquellos pacientes  que  cumplan  con  los \\nsiguientes criterios: \\n Buen estado general \\n Clasificación de gravedad<3 (ver cuadro 1) \\n Saturación de O\\n2\\n >94% \\n Tolerancia adecuada a la vía oral  \\n \\nPunto de \\nBuena \\nPráctica \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\n4. CUADROS O FIGURAS \\n \\nCUADRO I. ESCALA PARA VALORAR GRAVEDAD DE LA BRONQUIOLITIS \\n \\nPuntos 0 1 2 3 4 \\nFC: \\n \\n7 días-2 m 125-152  153-180 > 180   \\n(Edad) \\n2-12 m 120-140 140-160 > 160 \\n \\n12-24 m <110 110-160 > 160 \\nFR: \\n<2 m < 57  57-66  > 66 \\n(Edad) \\n2-6 m < 53  53-62 > 62 \\n \\n6-12 m < 47  47-55  > 55 \\n \\n12-24 m <30 30-40 >40 \\nRelación I/E \\nNormal Simétrica Invertida \\n(espiración \\nProlongada) \\nEsfuerzo \\nRespiratorio \\nNinguno Tiraje \\nSubcostal o \\nIntercostal \\nInferior  \\n+ tiraje \\nsupraesternal \\no aleteo nasal \\n+ tiraje \\nsupraesternal \\ny aleteo nasal \\n(tiraje \\nuniversal) \\nSibilancias \\nNo Al final de la \\nespiración \\nEn toda la \\nespiración  \\nInspiratorias y \\nespiratorias \\nTórax  \\nSilente \\n \\nEstertores \\nNo Crepitantes \\nen 1 campo \\nCrepitantes en \\n2 campos \\nCrepitantes en \\n3 campos \\nCrepitantes en \\n4 campos \\n \\n     \\nFC: Frecuencia Cardiaca/min; FR: Frecuencia respiratoria/min; I/E: Relación Inspiración-Espiración  \\nm: meses \\nBronquiolitis (estime la gravedad con base en la suma de los puntos encontrados en la valoración clínica): \\n leve 1 – 3  \\n moderada 4 – 7 y  \\n grave 8 – 14 puntos \\nFuente: Ramos Fernández JM, et al. Validación de una escala clínica de severidad de la bronquiolitisaguda.  \\nAnPediatr (Barc). 2013. \\nHartman ME and Cheifetz IM. PediatricEmergencies and resuscitation. In kliegman RM et al. Eds. Nelson \\nText \\nfile:///C|/Users/SONY/Desktop/GPC%20Bronquiolitis%20Actualizacion%202014/dx.doi.org/10.1016/\\nj.anpedi.2013.06.020 \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nRECOMENDACIONES DE BRONQUIOLITIS PARA PADRES Y CUIDADORES \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nLuz bronquiolar \\nnormal \\nBronquio \\nPulmones \\n¿Qué es la bronquiolitis? \\nLa bronquiolitis es resultado de la disminución del paso \\nde  aire  en  los  pulmones  de el/la  niño/a por \\ninflamación bronquial. Esto puede hacer que sea difícil \\npara el/la niño/a respirar.  \\n \\nLa bronquiolitis puede ser  causada por varios virus, \\npero el mayor número de casos es producida por el \\nVirus  Syncytial respiratorio (RSV). \\n \\nLa  mayor  parte  de niñas/niños que  sufre  esta \\ninfección se encuentran en los primeros dos años de \\nvida.  Es  más  frecuente  en  los  meses  de  invierno  y \\nusualmente solo causa síntomas de un leve resfriado. \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\n¿Se puede prevenir la bronquiolitis? \\nLos virus que producen los cuadros de bronquiolitis, son los responsables de los cuadros de gripa / \\nresfriado de niñas/niños mayores y adultos, por lo tanto se sugieren las siguientes medidas:  \\n Lavado  de  manos  con  agua  y  jabón  o  aplicación  de  alcohol  gel  : antes  y  después  de  la \\npreparación de alimentos y de tocar a el/la niño/a. \\n Lactancia materna: Uso de lactancia materna exclusiva los primeros 6 meses de edad y si es \\nposible continuar hasta el primer año de vida. \\n Evitar  lugares  concurridos:  plazas,  cines, centros  comerciales  o  lugares  de  esparcimiento \\ndonde incremente la probabilidad de contacto con enfermos. \\n Evitar el contacto con enfermos de infección de vías aéreas superiores: evitar el contacto de \\npersonas ya con síntomas de la enfermedad (hermanos menores de 5 años y  adultos). \\n Evitar exposición al humo de tabaco: en cigarro o ropa impregnada con el olor.  \\n \\n¿Cuáles son los síntomas de bronquiolitis? \\n La bronquiolitis inicia como un resfriado común. El/la niño/a puede tener congestión o salida \\nde moco nasal y algunas veces temperatura y tos. \\n Después de algunos días con el cuadro , la tos puede empeorar. \\n La respiración de el/la niño/a es más rápida de lo normal y puede ser ruidosa,  lo cual puede \\nproducir un mayor esfuerzo para respirar.  \\n Algunas veces en niñas/niños muy pequeños, bronquiolitis puede producir pausas en su \\nrespiración. \\n Cuando la respiración incrementa y causa dificultad para respirar, el niño puede no ser capaz \\nde tomar la cantidad usual de seno materno o formula láctea, con disminución del número de \\npañales con orina. \\n El/la niño/a puede estar decaído después de alimentarse y volverse irritable o llorón.  \\n \\n¿Cómo puedo ayudar a mi bebe? \\n Si es difícil llevar a cabo la alimentación, trata de ofrecerle cantidades pequeñas de leche más \\nseguido. \\n Si el/la niño/a presenta fiebre, puedes utilizar fomentos de agua para disminuirla, o bañarlo en \\ntina con agua tibia. \\n La  bronquiolitis  es  causada  por  virus,  por  lo  cual  los  antibióticos    NO  PROVEEN  ningún \\nbeneficio.  \\n \\n¿Cuántos días dura la bronquiolitis? \\n La mayoría de niñas/niños  con bronquiolitis, logran la recuperación después de dos semanas, \\naunque la mayoría puede continuar con tos por algunas semanas más. \\n El/la niño/a puede  regresar a cuidados de guardería tan pronto como su alimentación sea \\nnormal y no presente dificultad en la respiración. \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n Si hay una adecuada recuperación , no es necesario nueva valoración medica.  \\n \\n¿Cuándo debo acudir al medico? \\n Cuando el/la niño/a tenga dificultad para respirar (respiración rápida jadeante, hundimiento \\nde costillas,  hundimiento del pecho, al respirar apertura las alas de la nariz, o respiración muy \\nsuperficial que impide que se expanda el pecho).  \\n Cuando disminuya la alimentación a la mitad de lo que usualmente ingiere el/la niño/a.  \\n Deje de orinar en 4 horas. \\n Fiebre mayor a 38°C. \\n Irritabilidad, llanto difícil de controlar o que se encuentre somnoliento. \\n Durante la respiración presente pausas para respirar.  \\n Saliva espesa con ausencia de lagrimas durante el llanto.  \\n Cambio de coloración de piel o labios"}'::jsonb, false, 5627, '2026-11-25 23:40:58.48+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '076-08'), 'GER', '{"alarmas": "Referir a segundo nivel si crisis hipertensiva con o sin lesión a órgano blanco, sospecha de hipertensión secundaria (renovascular o endocrina), hipertensión arterial difícil de controlar (requiere tres o más fármacos), presencia o sospecha de daño a órgano blanco, insuficiencia renal progresiva, retinopatía avanzada, insuficiencia cardíaca grave, arritmias documentadas, o eventos cardiovasculares significativos. Pacientes con hipertensión acompañada de complicaciones deben ser evaluados por oftalmología, medicina interna y cardiología anualmente.", "prevencion": "Promover estilos de vida saludables: dieta DASH con bajo consumo de sodio (<1.5-2 g/día en jóvenes y adultos, menor en mayores de 70 años), alta en frutas, verduras y bajo en grasas saturadas. Reducir peso para lograr IMC entre 18.5 y 24.9 kg/m2. Limitar consumo de alcohol a máximo 20-30 g/día hombres, 10-20 g/día mujeres. Suspender hábito tabáquico. Realizar ejercicio físico aeróbico moderado (30-60 min, 4-7 días/semana, intensidad 60-80% FC máxima). Manejo del estrés con técnicas de relajación y terapia conductual. Reducir consumo de cafeína excesiva. Educación continua y apoyo para adherencia y autocontrol. Evitar alimentos procesados con alto contenido en sal. Participación comunitaria para disminuir ingesta de sodio en alimentación general.", "diagnostico": "Hipertensión arterial sistémica se define por presión arterial persistente ≥140/90 mmHg, confirmada con al menos dos mediciones en consulta en citas diferentes o bitácora domiciliaria positiva. Evaluar riesgo cardiovascular con modelo SCORE en pacientes sin enfermedad cardiovascular, renal o diabetes. Estudios básicos: biometría hemática, química sanguínea, perfil lipídico, examen general de orina, electrocardiograma y evaluación de daño a órgano blanco (microalbuminuria, TFG, ecocardiograma si está disponible). Palpación de pulso para detectar arritmias. Medición de presión arterial realizada por personal capacitado mediante técnica estandarizada con esfigmomanómetro manual o automátco.", "seguimiento": "Control periódico con visitas cada 2-4 semanas tras iniciar o modificar tratamiento hasta estabilización. Luego seguimiento cada 3 meses en pacientes con riesgo cardiovascular bajo y control adecuado; en riesgo alto o descontrol cada 2-4 semanas según evolución. Reevaluar daño a órgano blanco y factores de riesgo cada 1-2 años según condiciones clínicas. En diabéticos y con enfermedad renal controlar función renal y potasio sérico cada 4-6 meses. Realizar valoración geriátrica una vez al año en pacientes ≥70 años. Registrar presión arterial idealmente mediante monitoreo domiciliario para ajustar tratamiento. Refuerzo continuo de cambio en estilo de vida.", "tratamiento": "Iniciar tratamiento farmacológico cuando PAS ≥140 mmHg o PAD ≥90 mmHg confirmado en consulta o bitácora; para PAS ≥160 mmHg o PAD ≥100 mmHg iniciar inmediata farmacoterapia. Fármacos de primera línea: diuréticos tiazídicos (e.g. hidroclorotiazida 12.5-100 mg/día, clortalidona 12.5-50 mg/día), IECA (enalapril 10-60 mg/día, captopril 25-100 mg/día), ARA II (losartán 25-200 mg/día, valsartán 80-320 mg/día), bloqueadores de calcio de acción prolongada (amlodipino 5-10 mg/día, nifedipino 30-60 mg/día), beta-bloqueadores (metoprolol 50-300 mg/día en 2-3 tomas). Empezar a dosis bajas y aumentar gradualmente según respuesta y tolerancia. Utilizar combinaciones de primera línea si no se alcanza meta: tiazidas + IECA o ARA II + bloqueador calcio. Evitar combinar IECA y ARA II. En hipertensión sistólica aislada usar tiazidas, bloqueadores de calcio o ARA II. En ancianos iniciar tratamiento si PAS ≥160 mmHg, meta PAS <140 mmHg con cuidado en hipoperfusión (diastólica >65 mmHg). En diabetes iniciar si PAS >140 mmHg, preferir IECA o ARA II con evidencia de proteinuria. En insuficiencia cardíaca usar IECA, beta-bloqueadores, diuréticos. Duración indefinida con monitoreo."}'::jsonb, false, 42552, '2026-11-25 23:44:56.181+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '076-08'), 'GRR', E'{"alarmas": "Presión arterial ≥180/110 mm Hg o crisis hipertensiva con daño a órgano blanco, sospecha de hipertensión secundaria (renovascular o endocrina), hipertensión resistente luego de tres fármacos, pacientes con daño a órgano blanco manifiesto, diabetes con nefropatía, insuficiencia cardíaca grave, o sospecha de complicaciones deben ser referidos a segundo nivel para evaluación y manejo especializado.", "prevencion": "Modificar estilos de vida incluyendo dieta hiposódica (ingesta de sal 3-6 g/día según edad), alimentación tipo DASH rica en frutas, verduras, granos enteros y baja en grasas saturadas, disminución de peso para IMC 18.5-24.9 kg/m2, manejo del estrés, ejercicio aeróbico moderado 30 minutos/día 5-7 días/semana, suspensión de tabaco y reducción de consumo de alcohol a ≤2 copas/día. Promover reducción del consumo de cafeína y productos con sal industrializada. Fomentar educación y grupos de apoyo para control de factores de riesgo.", "diagnostico": "Hipertensión arterial sistémica se define como presión arterial persistente ≥140/90 mm Hg; diagnóstico confirmado en segunda consulta tras una medición inicial elevada y bitácora positiva de presión arterial en domicilio. Realizar historia clínica completa, exploración física, y estudios básicos: hemograma, química sanguínea, electrolitos, perfil lipídico, ácido úrico, examen general de orina; valorar daño a órgano blanco (exploración neurológica, oftalmológica) y riesgo cardiovascular con modelo SCORE. ECG basal y Holter sólo si hay sospecha clínica.", "seguimiento": "Control clínico cada 2-4 semanas después de iniciar tratamiento farmacológico hasta estabilización; pacientes con buen control y riesgo cardiovascular bajo pueden ser evaluados cada 3 meses. Realizar estudios de laboratorio al menos anual en pacientes sin comorbilidades, cada 4-6 meses si hay comorbilidades. Valoración geriátrica anual en adultos mayores ≥70 años. Vigilar adherencia, efectos adversos y ajuste terapéutico continuo en primer nivel.", "tratamiento": "Iniciar con monoterapia: diuréticos tiazídicos (hidroclorotiazida 12.5-25 mg VO. diario), IECA (enalapril 10-60 mg/día VO), ARA II, calcio antagonistas o beta-bloqueadores según tolerancia y comorbilidades; ajustar dosis a máxima tolerada antes de agregar segundo fármaco y combinar hasta tres fármacos (tiazidas + IECA/ARA II + calcio antagonista). No combinar IECA con ARA II. Para hipertensión resistente, considerar espironolactona 25 mg/día. En condiciones especiales como diabetes, usar IECA/ARA II + calcio antagonistas y ajustar metas presoras (ej. <130/80 mm Hg en diabetes). Duración indefinida, ajustar según control.", "texto_completo": "Diagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nGUÍA DE PRÁCTICA CLÍNICA\\n \\nGPC\\n \\n \\n \\nDiagnóstico y Tratamiento de la \\nH\\nIPERTENSIÓN ARTERIAL \\n \\nen el Primer Nivel de Atención\\n \\n \\n \\n \\n \\nGuía de Referencia Rápida \\nCatálogo Maestro de Guías de Práctica Clínica:\\n IMSS-076-08 \\n \\nActualización \\n2014 \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n \\n \\n \\n1. CLASIFICACIÓN ......................................................................................................................................... 3\\n \\n2. DEFINICIÓN Y CONTEXTO ........................................................................................................................... 4\\n \\n3. HISTORIA NATURAL DE LA HIPERTENSIÓN ARTERIAL .......................................................................... 5\\n \\n4. ESCALAS DE CLASIFICACIÓN CLÍNICA ..................................................................................................... 11\\n \\n5. DIAGRAMAS DE FLUJO ............................................................................................................................... 21\\n \\nÍndice \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n1. Clasificación \\n \\n \\n \\nCIE-10:I10 HIPERTENSIÓN ARTERIAL ESENCIAL PRIMARIA\\n \\n \\nGPC: \\nDIAGNÓSTICO Y TRATAMIENTO DE LA HIPERTENSIÓN \\nARTERIAL EN EL PRIMER NIVEL DE ATENCIÓN\\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nLa Hipertensión Arterial Sistémica es  un Síndrome de  etiología múltiple caracterizado  por  la  elevación \\npersistente de las cifras de presión arterial a cifras ≥ 140/90 ml/Hg. \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n2. Definición y Contexto \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n \\n \\n \\n \\n \\n \\n3.  \\nPromoción \\n \\n Aconsejar a las personas mantener un índice de masa corporal entre 18.5 y 24.9 kg/m2, para prevenir el \\nriesgo de hipertensión arterial sistémica. \\n Recomendar terapias conductuales acompañadas de técnicas de relajación para el manejo del estrés así \\ncomo  un  plan  de  alimentación  con  consumo  alto  de  frutas  y  vegetales  e  ingesta  baja  de  grasas \\nsaturadas. \\n Aconsejar al paciente la reducción de sal en la dieta diaria familiar y la suspensión del hábito tabáquico y \\nofrecer su integración a grupos de apoyo. \\n Sugerir  al  paciente,  disminuir  el  consumo  excesivo  de  café y  otros  productos  con  alto  contenido  en \\ncafeína. \\n Proponer al paciente, realizar cambios en su estilo de vida, dado que la suma de varias intervenciones \\nreduce la presión sistólica 10 mm Hg o más, aproximadamente. \\n \\nPrevención \\n  \\n Realizar exploración neurológica para identificar probable daño a órgano blanco (cerebro). \\n Realizar examen  de agudeza  visual  (cuadro de  Snellen),  así  como  exploración  de fondo  de ojo  para \\nidentificar retinopatía. \\n Estimar Riesgo Cardiovascular en los pacientes adultos \\n \\nDiagnóstico \\n \\n Es conveniente el escrutinio de la hipertensión arterial a través de la toma periódica de la presión arterial \\nmediante la estrategia oportunista en la consulta médica. \\n Es  preferible  que  las  determinaciones  de  la  presión  arterial  en  las  unidades  de  salud  se  realicen  por \\npersonal de enfermería capacitado. \\n Integrar diagnóstico de HAS desde la primera consulta médica en todo paciente diabético con Daño a \\nÓrgano Blanco (DOB) o datos de insuficiencia renal de moderada a grave (filtración glomerular <60 \\nmL/min/m2), que presente cifras de más de 140/90 mm Hg. \\n Establecer diagnóstico de HAS en la segunda consulta médica (al mes de la primera determinación de la \\npresión  arterial)  cuando  el  paciente manifieste:  Presión  Arterial  >  140/90  mm  Hg,  bitácora  positiva \\n(registro de presión arterial en su domicilio) o ambas situaciones. \\n Estratificar el riesgo cardiovascular utilizando el modelo SCORE en personas con HAS asintomáticas, sin \\nenfermedad cardiovascular, renal o diabetes. \\n Buscar de manera intencionada DOB particularmente en aquellos casos con riesgo moderado o alto, dado \\nque predice la mortalidad independientemente del puntaje de SCORE. \\n3. Historia Natural de la Hipertensión Arterial \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n Realizar una adecuada historia clínica con anamnesis detallada incluyendo historia familiar, factores de \\nriesgo y una exploración física completa, para identificar la presencia de signos y síntomas relacionados a \\nhipertensión secundaria, así como establecer el grado de DOB. \\n Determinar la presión arterial conforme a la técnica previamente descrita.  \\n Tomar el pulso en reposo desde la primera consulta médica. \\n Investigar, a profundidad: Datos clínicos de DOB y datos sugestivos de hipertensión secundaria. \\n El protocolo de estudio del paciente con HAS consiste en:  \\na) Citometría hemática \\nb) Química sanguínea y \\nc) Electrolíticos séricos, \\nd) Ácido úrico \\ne) Perfil del lípidos incluyendo HDL, LDL; colesterol total y triglicéridos y \\nf) Examen general de orina \\n \\n En establecimientos donde se cuenten con los recursos y el personal capacitado para la realización e \\ninterpretación de ECG, se sugiere un estudio basal de 12 derivaciones, con el propósito de investigar \\nhipertrofia ventricular y bloqueo. Así como Holter (MAPA) para las siguientes situaciones: a) discordancia \\nde la presión arterial registrada en casa y el consultorio; b) sospecha de hipertensión nocturna por daño \\nrenal o apnea del sueño, y c) sospecha de hipotensión autonómica. \\n En aquellos lugares, en los que se cuenten con el recurso y personal capacitado, se sugiere la realización \\nde telerradiografía de tórax (posterior-anterior), como parte del protocolo de estudio \\n \\n \\nTratamiento Farmacológico \\n \\nSin condiciones especiales: \\n \\n Recomendar  para  el  inicio  y  mantenimiento  de  los  tratamientos,  tanto  para  monoterapia  como \\ncombinada; Diuréticos tipo tiazidas, IECA, ARA II, calcio-antagonistas o beta-bloqueadores \\n Iniciar el tratamiento como monoterapia, utilizando diuréticos del tipo de tiazidas.  \\n Utilizar fármacos de primera línea con prescripción razonada, a dosis bajas e incrementar gradualmente, \\ndependiendo de la respuesta y control de la presión arterial. \\n Administrar las dosis máximas de los fármacos prescritos antes de agregar un segundo o tercer fármaco \\nen el régimen elegido. \\n En caso de requerir la combinación de 3 fármacos, se recomienda:  \\n1. Tiazidas, más \\n2. IECA o ARA II, más \\n3. Calcio-antagonistas. \\n No combinar IECA y ARA-II en un mismo régimen terapéutico, para el paciente con HAS. \\n Prescribir tratamiento antihipertensivo cuando la PAS ≥ 140 mmHg y/o PAd ≥ 90 mmHg registrada en la \\nbitácora del paciente y/o en la segunda consulta, después de las 2 semanas o simultáneamente, al inicio \\nde los cambios de estilo de vida adoptados por el paciente. \\n Iniciar tratamiento farmacológico en pacientes con PAS ≥160mmHg y PAD ≥100mmHg, sin DOB ni otros \\nfactores de RCV; así como en elevación persistente de PAS y PAD. \\n Considerar para los regímenes, combinaciones de medicamentos de primera línea cuando las cifras de \\npresión arterial continúan por arriba de la meta ≥20 mm Hg para PAS o ≥10 mm Hg para PAD. \\n Para el tratamiento de hipertensión sistólica aislada no controlada, se sugiere la combinación de dos \\nfármacos  de  primera  línea  o  en  presencia  de  eventos  adversos  utilizar  -bloqueadores,  IECA o  calcio \\nantagonista. \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n La iniciación inmediata del tratamiento farmacológico se recomienda en personas con PAS ≥180mmHg y \\nPAD ≥110mmHg, con cualquier nivel de RCV. \\n Para el tratamiento de la hipertensión resistente considerar el uso de espironolactona a dosis de 25 mg \\ncada 24 horas, vigilando su utilización en enfermos con disminución de la Tasa de Filtración Glomerular \\n(TFG). \\n Para el caso de pobre tolerancia o contraindicaciones a espironolactona, o falta de eficacia terapéutica \\nconsiderar la utilización de   o   bloqueadores. \\n En pacientes que presenten un adecuado control de la presión arterial (<140/90 mm Hg) con un régimen \\nque incluya un beta-bloqueador utilizado por largo tiempo; no representa una indicación absoluta para \\nremplazarse. \\n \\nCon condiciones especiales: \\n \\nA) Paciente Anciano \\n Iniciar tratamiento farmacológico con PAS ≥ 160 mm Hg. \\n Cuando  no  se  inicia  con  un  diurético  de  tiazidas  de  primera  elección    adicionar  este  al  régimen  del \\ntratamiento como segunda línea.  \\n Ante la falla terapéutica de 3 fármacos, se recomienda buscar las posibles causas, entre ellas:  \\na. Pobre adherencia al tratamiento \\nb. Sobrecarga de volumen diastólico \\nc. Interacciones farmacológicas (ver cuadro XVI) \\nd. Condiciones asociadas (obesidad, tabaquismo, consumo excesivo de alcohol, resistencia a la insulina, \\npseudoresistencia al tratamiento y pseudohipertensión). \\n \\n En <80 años, se considera meta terapéutica de PAS < 140 mm Hg, y de PAD no menos de 65 mm Hg.  \\n En >80 años con una PAS inicial ≥ 160 mm Hg, se recomienda reducir la PA entre 140 y 150 mm Hg, una \\nvez probada una buena condición física y mental, , así como disminuir la dosis de los fármacos de acuerdo \\na la tolerancia y sintomatología. \\n En un paciente con fragilidad depositar la decisión de terapia antihipertensiva al médico tratante y bajo el \\nmonitoreo de los efectos clínicos del tratamiento. \\n El tratamiento anti hipertensivo bien tolerado en un paciente anciano, que alcanza los 80 años de edad, \\nconsiderar su continuidad. \\n Se recomiendan diuréticos y calcio antagonistas como fármacos de primera línea para la hipertensión \\narterial sistólica aislada. \\n Se sugiere incluir en el esquema terapéutico de un paciente anciano con HAS, fármacos de primera línea \\nque no sean beta-bloqueadores.  \\n \\nB) Presencia de comorbilidades \\n \\n Prescribir terapia antihipertensiva si PAS es 140 a 160 mm Hg en presencia de DOB.  \\n Dar tratamiento farmacológico en pacientes con HAS, con RCV alto por DOB, Diabetes Mellitus (DM), \\nEnfermedad Cardiovascular (ECV) o Enfermedad Renal Crónica (ERC). \\n En pacientes de HAS con DM, iniciar tratamiento cuando la PAS se encuentre ≥ 140 mm Hg. \\n En el paciente con DM se recomienda, como orden de preferencia en la elección del fármaco (de primera \\nlínea), los siguientes: \\n1. IECA o ARA II, \\n2. Calcio-antagonistas, y \\n3. Tiazidas a dosis bajas  \\n Realizar la elección del tratamiento farmacológico en el paciente con DM valorando siempre la presencia \\nde ERC, así como la excreción urinaria de albumina y otras comorbilidades. \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n Utilizar terapia combinada con IECA o ARA II especialmente en enfermos con diabetes y proteinuria o \\nmicroalbuminuria más calcio antagonistas de efecto prolongado  \\n En el paciente con DM, la meta recomendada es PAS <130 mm Hg y PAD < 80 mm Hg. \\n \\n Se recomienda en pacientes con síndrome metabólico: \\n1) Medidas generales:  \\na. Bajar de peso  \\nb. Realizar un programa de ejercicios aeróbicos.  \\n \\n2) Utilizar para la terapia combinada: \\na. IECA o ARA II, especialmente en enfermos con proteinuria o microalbuminuria \\nb. Calcio-antagonistas de efecto prolongado \\nc. Diuréticos ahorradores de potasio. \\n \\n En paciente con cardiopatía isquémica se recomienda mantener cifras de <130/80 mm Hg. \\n Preferir el uso de los beta-bloqueadores o calcio antagonistas como terapia inicial en los pacientes con \\nangina estable \\n Recomendar beta-bloqueadores en pacientes con infarto reciente \\n Recomendar  la combinación de un IECA y un calcio-antagonista en enfermos con alto RCV \\n No se recomienda prescribir calcio-antagonistas en presencia de insuficiencia cardíaca con congestión \\npulmonar o evidencia radiológica de la misma. \\n En insuficiencia cardiaca y disfunción sistólica, los IECA y los beta-bloqueadores se recomiendan como \\nterapia inicial. \\n En enfermos con insuficiencia cardíaca o disfunción grave del ventrículo izquierdo, se recomienda para el \\nrégimen terapéutico: \\na. Diuréticos, \\nb. beta-bloqueadores, \\nc. IECA o ARA II. \\n Utilizar calcio-antagonistas cuando los beta-bloqueadores están contraindicados o no son efectivos. \\n En enfermedad cardiovascular: \\n1) Alcanzar la meta recomendable: PAS <140 mm Hg \\n2) Utilizar terapia combinada con IECA o ARA II más calcio-antagonista \\n \\n En pacientes con HAS asociada a enfermedad cerebrovascular se recomienda la combinación de IECA y \\ndiuréticos de tiazidas. \\n En pacientes con HAS e insuficiencia renal no asociada a DM y en ausencia de estenosis de la arteria \\nrenal, se recomienda de primera línea: IECA. \\n En Hipertensión arterial y nefropatía diabética o no diabética, se recomienda utilizar terapia combinada \\ncon: \\na. IECA o ARA II \\nb. Calcio antagonistas de efecto prolongado \\nc. Los diuréticos de asa reemplazan a las tiazidas cuando la creatinina sérica es 1.5 mg/dL o la TFG es < \\n30 mL/min/1.73 m. \\n2) Mantener la meta recomendable PAS <130 mm Hg, en presencia de proteinuria. \\n \\nTratamiento No Farmacológico\\n \\n \\n Realizar cambios en el estilo de vida que incluyan una mejora en la alimentación y actividad física diaria. \\n Para pacientes con HAS se recomienda una ingesta de sodio: \\n1. 1,500 mg/día en menores de 50 años \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n2. 1,300 mg/día en 51 a 70 años \\n3. 1,200 mg/ día en mayores de 70 años \\n Recomendar en la dieta, una ingesta de sal de 5 a 6 g por día y reducir a 3 g por día por sus posibles \\nefectos benéficos a largo plazo. \\n Implementar  políticas  de  salud  que  incluyan  la  participación  y  responsabilidad  social  de  la  industria \\nalimentaria, para lograr la disminución en el consumo de sal en la dieta de la población ya que el 80% del \\nconsumo total de sal por día se encuentra en los productos industrializados. \\n En pacientes hipertensos se recomienda reducción de peso corporal para lograr un IMC de 25 Kg/m2. \\n Proporcionar al paciente los siguientes consejos para disminuir el consumo de sal y sodio: \\n Escoger comidas y condimentos con poca cantidad de sal. \\n Comprar vegetales frescos, congelados o enlatados sin sal añadida. \\n Consumir aves frescas, pescados y cortes de carne delgado sin grasa en vez de los tipos enlatados, \\nahumados o procesados. \\n Escoger para el desayuno cereales con bajo contenido de sodio \\n Evitar el consumo de alimentos curados (jamón, tocino, etc.), alimentos enlatados en agua salada y \\ncondimentos.  \\n Limitar el consumo de salsa de soya, salsa teriyaki, inglesa, cátsup y mostaza.  \\n Cocinar con hierbas, especias, limón, lima, vinagre o mezclas de condimentos sin sal.  \\n Comenzar por reducir la cantidad de sal que habitualmente se usa a la mitad. \\n Disminuir el consumo de arroz instantáneo y comidas precocinadas. \\n Escoger frutas y verduras frescas en lugar de aperitivos o botanas saladas. \\n Las frutas frescas son recomendadas, aunque con precaución; debido a su alto contenido de hidratos de \\ncarbono pueden promover ganancia de peso.  \\n Recomendar 4 a 5 frutas por día (por ejemplo: naranja, plátano, toronja o melón, entre otros). \\n Aumentar el consumo de vegetales, fibra soluble, granos enteros y proteínas de origen vegetal, así como \\nreducir el consumo de grasas saturadas. \\n En pacientes con HAS se recomienda:  \\na. Consumo de pescado por lo menos 2 veces por semana. \\nb. Consumo de frutas y vegetales de 300 a 400 gr al día. \\n Se recomienda adoptar un plan alimenticio (DASH) con alto consumo de frutas, verduras y productos \\nlácteos bajos en grasa, fibra dietética y soluble, granos enteros y proteínas de origen vegetal, así como \\ncon bajo contenido grasas saturadas y colesterol. \\n El plan DASH es rico en magnesio, potasio, calcio, proteínas y fibra, considerar que la interacción de todos \\nestos nutrientes ayuda a reducir la presión arterial. \\n En adultos sanos limitar el consumo de alcohol a 2 copas o menos por día, sin exceder por semana: 14 \\nbebidas  estándar  en  hombres  y  9  bebidas  estándar  en  mujeres.  (Por  ejemplo:  una  bebida  estándar \\n[comercial] equivale a: 13.6 gr o 17.2 mL de etanol o aproximadamente, 44 ml [1.5 oz] de 80° [40%] \\nbebidas preparadas; 355 ml [12 oz] de cerveza a 5%; o 148 ml [5 oz] de vino a 12%). \\n Aconsejar al paciente realizar ejercicio aeróbico moderado al menos 30 min al día, de 5 a 7 días por \\nsemana. \\n Proporcionar  al  paciente  un  programa  de  ejercicios  aérobicos  (caminar,  trotar,  ciclismo,  aeróbico  o \\nnatación). \\n Enfatizar al paciente con HAS, no realizar ejercicios de resistencia isométrica. \\n Promoverse la suspensión del hábito tabáquico, y sugerirse la asistencia a grupos de apoyo, así como a \\nun consejero profesional \\n Se sugiere proporcionar consejo profesional y referir al paciente a grupos de apoyo para el control de los \\nfactores modificables. \\n Considerar la heterogeneidad del paciente adulto mayor antes de recomendarse el consumo y cantidad \\nde sal, al día. \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\nVigilancia y Seguimiento\\n \\n \\n Enfatizar el control de las causas asociadas HAS como son el sobrepeso y la obesidad; la dieta con alto \\ncontenido de sodio y grasas saturadas, así como la falta de actividad física y sedentarismo. \\n El paciente de HAS con RCV bajo y presión arterial controlada (meta alcanzada) puede evaluarse cada 3 \\nmeses, a criterio del médico tratante según la evolución y respuesta clínica. \\n El paciente con un RCV alto o descontrol en sus cifras de presión arterial se sugiere evaluarse cada 2 a 4 \\nsemanas, siendo necesario la individualización de cada caso dependiendo de la respuesta al tratamiento y \\nevolución clínica. \\n Después del inicio del tratamiento antihipertensivo con medicamentos se recomienda citar nuevamente \\nal paciente en intervalos de 2-4  semanas para  valorar respuesta y posibles reacciones adversas  por \\nmedicamentos. \\n Se recomienda individualizar la periodicidad de la determinación de los estudios de laboratorio con base \\nen la presencia de condiciones especiales. Se sugiere solicitar los estudios paraclínicos al menos una vez \\nal año en el paciente sin comorbilidades y cada 4-6 meses en el paciente con comorbilidades o con \\ncondiciones especiales, dependiendo de la evolución clínica y control del DOB.  \\n En  pacientes  hipertensos  con  otras  condiciones  de  alto  riesgo  (uso  de  anticoagulantes  orales, \\nenfermedad vascular cerebral, riñón único, alteraciones de la coagulación, aneurismas, entre otras), se \\nrecomienda control estricto de la presión arterial para alcanzar la meta recomendada de acuerdo a cada \\ncondición asociada en el paciente. \\n Se recomienda realizar una valoración geriátrica integral a todo paciente anciano ≥70 años de edad con \\nHAS, por lo menos una vez al año en atención primaria. \\n \\nDías de Incapacidad\\n \\n \\n El reposo debe ser indicado en casos de hipertensión grave o con repercusión a órgano blanco en tanto se \\nlogra su control con las medidas terapéuticas adecuadas. \\n \\nCriterios de Referencia\\n \\n \\n Ante la sospecha de hipertensión secundaria (renovascular o endócrina) el paciente debe ser referido a \\nsegundo nivel para evaluación completa por el servicio correspondiente. \\n En casos de crisis hipertensiva con o sin lesión a DOB, iniciar las medidas generales de tratamiento y \\nreferir a 2° o 3° nivel para su evaluación integral y control de la hipertensión arterial, según sea el caso. \\n Si  el  paciente  presuntamente  requiere  de  un  cuarto  fármaco  para  el  control  de  la  presión  arterial, \\nconsiderar el envío al médico especialista en el segundo nivel.  \\n Se  recomienda  que  los  pacientes  hipertensos  con  complicaciones  (HAS  de  difícil  control,  evidencia  o \\nsospecha de DOB) se envíen a evaluación por 2º nivel al momento de su detección. \\n El paciente hipertenso puede ser enviado anualmente a valoración oftalmológica, y a medicina interna \\ncon el propósito de detectar y controlar oportunamente la aparición de lesiones a órgano blanco.  \\n El  paciente  hipertenso  controlado  en  situaciones  especiales  (complicaciones  por  HAS  o  diabetes  se \\npropone individualizar el caso para la vigilancia y seguimiento en el primer nivel.  \\n Se sugiere enviarse al paciente para valoración cardiológica, por antecedente, sospecha o presencia de \\ndaño cardiovascular, anualmente.  \\n El paciente hipertenso puede ser enviado a valoración cardiológica, por HAS de difícil control. \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n \\n \\n \\n \\n \\n \\nCUADRO I. MEDICIÓN DE LA PRESIÓN SANGUÍNEA POR AUSCULTACIÓN \\n \\n Estandarizar el procedimiento tanto como sea posible. \\n Sentar al paciente relajado, tranquilo y en un ambiente adecuado. \\n Con su brazo extendido y apoyado, en línea en medio del esternón. \\n Enrollar correctamente el brazalete y colocar el manómetro.  Debe enrollarse el brazalete hasta la \\nmarca del rango de la circunferencia permitida, estas marcas deben ser vistas el inicio o al empezar a \\nenrollar el brazalete. \\n Palpar el pulso humeral en la fosa antecubital del brazo. \\n Inflar  rápidamente  el  brazalete  a  20  mmHg,  por  arriba  del  punto  en  donde  el  pulso  humeral \\ndesaparece. \\n Desinflar el brazalete y anotar la presión a la cual el pulso re aparece: aproximándose la presión \\nsistólica. \\n Re inflar el brazalete a 20 mmHg. Por arriba de donde desapareció  el pulso humeral \\n Usando una mano, el estetoscopio será colocado sobre la piel en el lugar de la arteria humeral, evitar \\ncolocarlo entre la piel y el brazalete. \\n Desinflar despacio el brazalete a 2 – 3 mm Hg por segundo, escuchando los sonidos de Korotkoff. \\n \\nFASE  I.- El  primer  sonido  es  un  pulso  leve  y  repetido  que  gradualmente  incrementa  en  intensidad  y \\nduración hasta dos latidos de menor intensidad consecutivos: marcando la presión sistólica \\nFASE II.-Un breve  periodo puede seguir cuando los sonidos son débiles, auscultación gap: en algunos \\npacientes los sonidos pueden desaparecer en su totalidad. \\nFASE III.-El retorno de los sonidos nítidos empezarán a ser claros en un corto tiempo. \\nFASE IV.-Los distintos sonidos desaparecen abruptamente iniciando un suave soplido. \\nFASE V.-En el registro que los sonidos desaparecen totalmente, marcan la presión diastólica. \\n \\n Cuando  los  sonidos  desparecen  rápidamente,  desinflar  completamente  el  brazalete  y  repetir  la \\nmedición de la presión. \\n Cuando sea posible tomar lecturas al inicio y al final de la consulta. \\n \\n \\nFuente: NICE, 2006. \\n \\n \\n4. Escalas de Clasificación Clínica\\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\nCUADRO II. DEFINICIÓN Y CLASIFICACIÓN DE LA PRESIÓN ARTERIAL (PA). \\n \\nCATAGORIA SISTOLICA (mm Hg) DIASTOLICA (mm Hg) \\nOptima < 120 <80 \\nNormal 120-129 80-84 \\nNormal alta 130-139 85-89 \\nHipertensión grado 1 140-159 90-99 \\nHipertensión grado 2 160-179 100-109 \\nHipertensión grado 3 > =180 >= 110 \\nHipertensión sistólica aislada > =140 <90 \\nLa hipertensión sistólica aislada debe evaluarse de acuerdo a los grados 1, 2, y 3; basada en la valoración \\nsistólica de los rangos indicados, si la presión diastólica es <90 mm Hg. \\nLos grados 1,2 y 3 corresponden a la calificación leve, moderada y grave respectivamente.  \\n \\nFuente: European Heart Journal, 2013. \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\nCUADRO III. ESTRATIFICACIÓN DEL RIESGO CARDIOVASCULAR (RCV) DE ACUERDO A FACTORES \\nDE RIESGOS Y OTROS PARAMETROS \\nEstimar RCV con base en el número de factores de riesgos que presente la persona, en ausencia de DM, DOB, ERC o \\nEnfermedad vascular establecida.  \\nFACTORES DE RIESGO (*) CRITERIOS PUNTAJE \\nSI=1/ NO=0 \\nSexo Masculino   \\nEdad (años)* Hombre: >55 \\nMujer:> 65 \\n \\nTabaquismo* Positivo  \\nDislipidemia* Colesterol:  > 190 mg/dl  \\nColesterol LDL: 115 mg/dl \\nColesterol HDL:  \\nHombres < 40 mg/dl \\nMujer: < 46 mg/dl \\nTriglicéridos: > 150 mg/dl \\nGlucosa anormal en ayuno* 102-125 mg/dl  \\nPrueba de tolerancia a la glucosa* Anormal  \\nObesidad* IMC > 30 (kg/m\\n2 \\nSC)  \\nCircunferencia abdominal  Hombres: 102 cm \\nMujeres: 88 cm \\n \\nHistoria familiar de ECV temprana* Hombre < 55 años \\nMujer < 65 años \\n \\n*Suma (total) de factores de riesgo (individuales) \\n \\nIdentificar a la persona con RCV MEDIANO - ALTO, independientemente de la presencia de los factores de riesgo(*) \\ncuando presente (datos):  \\na. DIABETES MELLITUS                                                                                                                                                   (si/no) \\nGlucosa plasmática y/o 126 mg/dl en 2 pruebas  \\nHb. Glucosilada y/o >7 % \\nGlucosa plasmática posprandial >198 mg/dl \\nb. DAÑO A ÓRGANO BLANCO ASINTOMÁTICO                                                                                                       (si/no) \\nEn el anciano, presión del pulso > 60 mm Hg  \\nERC con TFG 30-60 ml/min \\nMicroalbuminuria 30-300 mg/24 hrs \\nIdentificar a la persona con RCV ALTO, cuando presente: \\nENFERMEDAD RENAL O ENFERMEDAD VASCULAR ESTABLECIDA                                                                   (si/no) \\na. ERC con TFG < 30 ml/min ; Proteinuria > 300 mg/24 horas  \\nb. Retinopatía etapa avanzada Hemorragia, Exudados, papiledema  \\nc. Cardiovascular Infarto del miocardio, angina de pecho, y otras.  \\nd. Cerebrovascular Infarto,  hemorragia  cerebral, evento  transitorio \\nisquémico.  \\n \\nERC=  Enfermedad  Renal  Crónica,  ECV=  Enfermedad  Cardiovascular,  TFG=  Tasa  de  Filtración  Glomerular, \\nDOB= Daño a Órgano Blanco DM=Diabetes Mellitus.  \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\nNotas: La  calificación  del  RCV  se  obtiene  sumando  los  factores  individuales  y  dependiendo  de  las \\ncomorbilidades asociadas. Cuadro modificado para las unidades de primer nivel.  \\nFuente: ESH-ESC, 2013 \\n \\nCUADRO IV. GRADACIÓN DE RIESGO CARDIOVASCULAR DE ACUERDO A LAS CIFRAS DE PRESIÓN \\nARTERIAL Y LA PRESENCIA DE FACTORES DE RIESGOS Y DOB \\n \\nFactores  de  riesgo \\n(FR), \\nDOB asintomático o \\nenfermedad \\nPresión Arterial (mm Hg) \\nNormal alta \\nPAS 130-139 \\no PAD 85-89 \\nHAS Grado 1 \\nPAS 140-159 \\no PAD 90-99 \\nHAS Grado 2 \\nPAS 160-179 o \\nPAD 100-109 \\nHAS Grado 3 \\nPAS ≥ 180 o \\nPAD ≥ 110 \\nSin  otro  factor  de \\nriesgo \\n Riesgo  \\nBajo \\nRiesgo Moderado Riesgo  \\nAlto \\n1-2 factores de riesgo Riesgo Bajo Riesgo Moderado Riesgo  \\nModerado a Alto \\nRiesgo \\n Alto \\n≥ 3 factores de riesgo Riesgo   bajo   a \\nModerado \\nRiesgo  \\nModerado a Alto \\nRiesgo  \\nAlto \\nRiesgo  \\nAlto \\nDOB, ERC estado 3 o \\ndiabetes \\nRiesgo  \\nModerado a Alto \\nRiesgo  \\nAlto \\nRiesgo  \\nAlto \\nRiesgo Alto a  \\nMuy Alto \\nECV sintomática, ERC \\nestadio   ≥   4   o \\ndiabetes con DOB/FR \\nRiesgo  \\nMuy Alto \\nRiesgo  \\nMuy Alto \\nRiesgo  \\nMuy Alto \\nRiesgo \\n Muy Alto \\n \\nPA=  Presión  arterial; ERC=  enfermedad  renal  crónica;  CV  =  cardiovascular;  ECV  =  enfermedad  cardiovascular;  PAD= \\npresión arterial diastólica; HAS = hipertensión; DOB = daño a órgano blanco; FR = factores de riesgo; PAS = presión \\narterial sistólica. \\nFuente: ESH-ESC, 2013 \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\nCUADRO V. DIETA DASH* \\n \\nAlimento Ración  Descripción de alimentos (ejemplos) \\nCereales y tubérculos 7-8/día Pan de trigo entero, avena, palomitas de maíz. \\nVerduras  4-5/día \\nTomates, papas, zanahorias, judías, guisantes, calabaza, \\nespinaca  \\nFrutas  4-5/día Durazno, plátanos, uvas, naranjas, toronjas, melón.  \\nLácteos (1%)  2-3/día \\nsin grasa (descremada) o baja en grasa, sin grasa o yogurt \\nbajo en grasa, sin grasa o queso bajo en grasa  \\nLeguminosas 2-3/semana Frijoles, habas, lentejas \\nGrasas con proteína 4-5/semana Almendras, cacahuetes, nueces, semillas de girasol \\nGrasas sin proteínas 2-3/ día \\nMargarina blanda, mayonesa baja en grasa, vegetales  \\naceite (oliva, maíz, canola y cártamo)  \\nProductos de origen animal 5/día Carne cocida, pollo, pescado \\nAzucares** 5/semana \\nJarabe de arce, azúcar, jalea, mermelada, caramelos, \\nhelados. \\n \\nCUADRO VI. DISTRIBUCIÓN DE RACIONES RECOMENDADAS EN PACIENTES SIN CONDICIONES \\nESPECIALES DE ACUERDO A LA CANTIDAD DE CALORÍAS REQUERIDAS \\n \\nA. DIETA HIPOSÓDICA DE 1,200 CALORÍAS POR DÍA** \\nGrupo de alimento Ración/día \\nDistribución de raciones \\nDesayuno Comida Cena \\nVerduras 7 2 3 2 \\nFrutas 2 1 1 0 \\nCereales y Tubérculos 5 2 2 1 \\nAlimentos de origen animal 3 1 2 0 \\nLácteos 1 0 0 1 \\nGrasas sin proteína 3 1 1 1 \\nGrasas con Proteína 1 0 1 1 \\nAzúcares** 1 1 0 0 \\n \\nB. DIETA HIPOSÓDICA DE 1,500 CALORÍAS POR DÍA** \\nGrupo de alimento Ración/día \\nDistribución de raciones \\nDesayuno Comida Cena \\nVerduras 8 3 3 2 \\nFrutas 2 1 1 0 \\nCereales y Tubérculos 5 2 2 1 \\nAlimentos de origen animal 4 1 2 1 \\nLeche  2 1 0 1 \\nGrasas sin proteína 4 1 2 1 \\nGrasas con proteína 1 0 0 1 \\nAzúcares** 2 1 1 0 \\n*Fuente: Plan de alimentación DASH disponible en www.nhlbi.nih.gov/health/public/heart/hbp/tablero/new_dash.pdf \\n**Azucares: Distribuir las raciones entre los días de la semana, recomendando un consumo máximo de 5/semana. \\n***Dieta: 50% Carbohidratos, 20% proteínas, 30% lípidos \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\nCUADRO VII. ESPECIFICACIONES DE LA PORCIONES EN LA DIETA, POR CATEGORÍA DE ALIMENTOS \\n \\n \\nVERDURAS \\nAlimento Ración \\nAcelga cocida \\n1/2 taza \\nBrócoli cocido \\n1/2 taza \\nChampiñón cocido \\n1/2 taza \\nEspinaca cocida \\n1/2 taza \\nJitomate \\n1 pieza \\nLechuga   \\n3 tazas \\nNopal cocido   \\n1 taza \\nRábano   \\n2 tazas \\nVerdolaga cocida \\n1/2 taza \\n \\nGRASAS CON PROTEÍNAS \\nAlimento Ración \\nAlmendra  10 piezas \\nNuez  3 piezas \\nCacahuate tostado  14 piezas \\nSemilla de girasol 4 cucharitas \\nPistache  18 piezas \\n \\nLÁCTEOS \\nAlimento Ración \\nHelado con leche  ¾ taza \\nJocoque  ¾ taza \\nLeche descremada  1 taza \\nYogurt light  1 taza \\n \\nGRASAS SIN PROTEÍNA \\nAlimento Ración \\nAceite comestible 1 cucharadita \\nAceite de oliva 1 cucharadita \\nAderezo vinagreta 2 cucharaditas \\nAguacate 1/3 pieza \\nCrema 1 cucharadita \\nMantequilla 1 ½ cucharadita \\nMayonesa ½ cucharadita \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nPRODUCTOS DE ORIGEN ANIMAL \\nAlimento Ración \\nAtún en agua  35 g \\nBistec de res 35 g \\nChambarete  35 g \\nClara de huevo  2 piezas \\nCuete  40 g \\nFalda de res  35 g \\nFilete de pescado  45 g \\nFilete de res 35 g \\nFilete de salmón 30 g \\nHuevo cocido  1 pieza \\nMachaca  12 g \\nMilanesa de res  35 g \\nMolida de pollo  35 g \\nMuslo de pollo 1/3 pieza \\nPechuga de pollo  30 g \\nPierna de pollo  ½ pieza \\nQueso blanco 35 g \\nQueso cottage 3 cucharadas \\nRequesón  3 cucharadas \\nSardina 40 g \\nSirlón  25 g \\nTampiqueña 30 g \\n \\nCEREALES Y TUBÉRCULOS\\n \\nAlimento Ración \\nAmaranto  1/4 taza \\nArroz cocido 1/4 taza \\nAvena cocida  3/4 taza \\nBolillo sin migajón 1/3 pieza \\nEspagueti cocido 1/3 taza \\nFideo  1/2 taza \\nGalletas marías 5 piezas \\nMasa de maíz 45 g \\nPalitos de pan 3 piezas \\nPalomitas natural  3 tazas \\nPan de caja 1 pieza \\nTortilla de maíz  1 pieza \\n \\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\nFRUTAS \\nAlimento Ración \\nCerezas 20 piezas \\nChabacano   4 piezas \\nDurazno 2 piezas \\nFrambuesa 1 taza \\nFresa  17 piezas \\nHigo 3 piezas \\nKiwi 2 piezas \\nLima  3 piezas \\nMamey 1/3 pieza \\nMandarina 2 piezas \\nMango ataulfo 1 pieza \\nManzana  1 pieza \\nMelón  1 taza \\nNaranja   1 piezas \\nPapaya   1 taza \\nPasas  10 piezas \\nPera  ½ pieza \\nPerón 1 pieza \\nPiña 1 taza \\nPlátano  ½ pieza \\nSandia  1 taza \\nToronja  ½ pieza \\nUva roja  15 piezas \\nUva verde 18 piezas \\nZarzamora ¾ taza \\n \\nAZÚCARES \\nAlimento Ración \\nAte  15 g \\nAzúcar  2 cucharaditas \\nCajeta  2 cucharaditas \\nLeche condensada  2 cucharaditas \\nMermelada  2 cucharaditas \\nMiel de abeja 2 cucharaditas \\n \\nLEGUMINOSAS \\nAlimento Ración \\nAlubias, garbanzos, \\nhabas, lentejas \\ncocidas \\n1/2 taza \\nAlverjón 1/2 taza \\nFrijol canario, negro \\ncocido \\n1/2 taza \\nSoya cocida 1/3 taza \\nSoya texturizada \\nseca \\n35 gramos \\n*En caso de no permitir el uso de azúcares, \\nse sugiere utilizar algún edulcorante como \\nsucralosa y acesulfame K. \\n \\n \\nNota: g: gramos \\n \\nFuente: Federación Mexicana de Diabetes, \\nAC.  Disponible  en  URL  (acceso  2  enero, \\n2014): \\nhttp://www.fmdiabetes.org/fmd/pag/nut\\nricion.php?id=MTQ1. \\nReferencias             consultadas: \\nhttp://www.nutriciongrupobimbo.com/upl\\noads/pdf/tablas_equivalencias.pdf \\nSistema   Mexicano   de   Alimentos \\nEquivalentes,     segunda     Edición. \\nhttp://www.fns.org.mx/index.php?IdConte\\nnido=46&IdSubContenido=53 \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n18 \\n \\nGUÍA DE EJERCICIOS PARA EL PACIENTE CON HIPERTENSIÓN ARTERIAL SISTÉMICA \\n \\nEl consenso universal apoya la realización de actividad física como parte de la terapia en \\npacientes hipertensos, se recomienda la actividad física de intensidad moderada en la cual \\neste nivel de intensidad se alcanza con una frecuencia de 60 al 80% de la frecuencia cardiaca \\nmáxima. \\n \\nLa principal guía para la realización de ejercicio aeróbico es la frecuencia cardiaca, (entre el 60 \\nal 80% de la frecuencia cardiaca máxima), la cual puede ser obtenida mediante algún sistema \\nde  monitoreo  o  bien  a  través  de  la  prueba  de  esfuerzo;  en  ausencia  de  lo  anterior  y \\ntratándose de pacientes hipertensos controlados la frecuencia cardiaca máxima (FCM) puede \\nser calculada de la siguiente manera: \\n \\nFrecuencia cardiaca máxima = 220 – edad (en años) \\n \\nEjemplo, si un paciente tiene 55 años de edad tendríamos lo siguiente: 220-55=165, es decir, \\nsu FCM sería 165 latidos por minuto de lo que obtendríamos el 60% (99 latidos por minuto) y \\nel 80% (132 latidos por minuto) \\n \\nDebido al riesgo  de  los  pacientes  hipertensos  de  presentar enfermedad  cardiovascular  es \\nconveniente  realizar  una  prueba  de  esfuerzo  antes  de  iniciar  el  programa  de  ejercicio \\naeróbico, la prueba se recomienda para identificar isquemia, arritmias e isquemia miocárdica \\nasintomática entre otras. \\n \\nLas fases del programa de ejercicio terapéutico para el paciente hipertenso comprenden lo siguiente: \\na) Una fase de calentamiento \\nb) Una fase de ejercicio \\nAeróbico \\nb.Resistencia \\nc) Una fase de enfriamiento \\n \\nDescripción de cada una de las fases \\n \\nFASE DE CALENTAMIENTO: (realizar la toma del pulso en arteria radial a nivel de muñeca al iniciar y \\nfinalizar esta fase). Para el inicio de la actividad física existen diversas posibilidades de acuerdo a las \\ncondiciones del paciente y a las características de su entorno. Si es posible en esta fase, se puede \\nrealizar ejercicio aeróbico pero de baja intensidad como sería caminata o ciclismo por un periodo de 5 a \\n10 minutos, de lo contrario se deberán de realizar ejercicios de calistenia y de estiramiento por el \\nmismo periodo de tiempo y con la siguiente secuencia y número de repeticiones: \\nRealizar \\n10 \\nrepeticion\\nes de cada \\nejercicio \\n1A. Flexo-extensión de cuello. Flexión lateral de cuello hacia la derecha e izquierda \\n2A. Elevación-descenso de hombros. Movimientos circulares de hombros \\n3A. Con brazos extendidos al frente efectuar movimientos circulares \\n4A. Con brazos extendidos al frente efectuar flexo-extensión de codos \\n5A. Flexo-extensión de tronco con brazos extendidos \\n1B. Con manos entrelazadas realizar en forma simultánea flexo-extensión de muñeca. \\n2B. Con los dedos de las manos entrelazados se llevan los brazos extendidos hacia arriba \\ny se hace ligera hiper-extensión de tronco. \\n3B. Colocar la mano en el hombro contrario, la mano libre sujeta el codo flexionado y hace \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n19 \\n \\npresión hacia adentro, realizar en forma alternada. \\n4B. Llevar los brazos hacia atrás sujetando las manos (a la altura de la cintura), y tratar de \\nacercar ambos codos. \\n5B. De pie, apoyado sobre la mano izquierda, flexionar la rodilla derecha hacia atrás y \\nayudándose con la mano derecha sujetar el pie por el empeine acercando el talón al \\nglúteo del mismo lado, al completar las repeticiones se repite del lado contrario. \\n6B. De  pie, se adelanta la  pierna derecha y se flexiona, la pierna izquierda permanece \\nextendida,  se  realiza flexión de tronco  en esta  posición, después de completar las \\nrepeticiones se repite del lado contrario. \\n \\nFASE DE ACTIVIDAD FÍSICA MODERADA: (realizar la toma del pulso en arteria radial a nivel de muñeca \\nal iniciar y finalizar esta fase). \\n \\nTipo – aeróbico. Se recomienda realizar esta actividad en forma diaria. Puede practicarse  algunas de \\nlas siguientes modalidades, ciclismo, caminata (a paso enérgico), natación (pueden intercalarse por \\ndía), por un periodo de 30 a 45 minutos. En caso contrario se deberá efectuar la siguiente secuencia y \\nnúmero de repeticiones \\nRealizar  30 \\nrepeticiones \\nde    cada \\nejercicio \\n \\n1C. Movimientos alternos simulando la marcha \\n2C. Movimientos  alternos  simulando  la  marcha  y  coordinar  con  flexo-extensión  de \\nbrazos. \\n3C. Movimientos alternos simulando la marcha y coordinando con flexo-extensión de \\nhombros con los brazos extendidos. \\n4C. Movimientos alternos simulando la marcha y coordinar con abducción-aducción de \\nbrazos. \\n5C. Movimientos alternos simulando la marcha y coordinando con hiper-extensión de \\nhombros manteniendo los brazos extendidos. \\n6C. Flexión lateral de tronco con elevación lateral del brazo contrario sobre la cabeza, la \\nmano libre se apoya sobre la cintura. Realizar alternadamente. \\n7C. Flexión de tronco y de pierna derecha tratando con la mano izquierda de tocar el pie \\nderecho, el brazo contrario se lleva en extensión, se realiza en forma alterna. \\n8C. Desplazamiento  de  la  pierna  izquierda  por  el  frente  hacia  la  derecha,  la  pierna \\nderecha también se desplaza hacia el mismo lado con torsión de tronco (hacia la \\nderecha) y cruzando el brazo izquierdo por el frente y hacia atrás, se alterna del lado \\ncontrario. \\nTipo – Resistencia. Este tipo de actividad se recomienda llevarlo a cabo de 2 a 3 días por semana \\nempleando una variedad de ejercicios y usando diferente equipo. La intensidad ligera a muy ligera debe \\nusarse para pacientes adultos mayores o en pacientes que llevan una vida sedentaria. Los pacientes \\nhipertensos deben esperar al menos 48 horas entre las sesiones de este tipo de ejercicios. \\nRealizar 2 a \\n4  series  de \\ncada uno de \\nlos \\nejercicios, \\nempleando \\nde  10  a  15 \\nrepeticiones \\nde    cada \\nejercicio \\nEjemplos de los ejercicios que se pueden realizar: \\n1D. Cuclillas \\n2D. Abdominales \\n3D. Apoyo de ambas manos sobre una superficie (pared), los pies separados de la pared \\nla  misma  distancia  que  dan  los  brazos  extendidos,  sin  despegar  los  pies  del  suelo \\nflexionar los codos acercando el tronco a la pared, regresar a la posición de partida e \\niniciar nuevamente \\n4D. Levantar pesos aproximados a 1 kg. Elevando el brazo extendido y alternando con el \\ncontralateral \\n5D. Lanzar pesos aproximados a 1 kg (pueden ser costalitos de arena).  \\nUtilizar bandas elásticas  \\n6D. La práctica de Tai Chi Chua. \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n20 \\n \\nLos ejercicios de resistencia generalmente, en este tipo de programas, están dirigidos a los grandes grupos \\nmusculares. \\nEs  importante  mencionar  que  el  beneficio  que  se  obtiene  con  los  ejercicios  de  resistencia  se  pierde \\nrápidamente con la inactividad sobretodo en individuos adultos mayores. \\n \\nFASE DE ENFRIAMIENTO: (realizar la toma del pulso en arteria radial a nivel de de muñeca al iniciar y \\nfinalizar esta fase). \\nRealizar  10 \\nrepeticiones \\nde    cada \\nejercicio \\n \\nRepetir la serie de los primeros 5 ejercicios (del 1A. al 5A.) \\nRealizar serie de respiraciones profundas con las manos a la cintura, llevando los \\nbrazos hacia atrás durante la inhalación y al frente durante la exhalación. \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n21 \\n \\n \\n \\n \\n \\n \\n \\nFLUJOGRAMAS 1-2. DETECCIÓN, DIAGNÓSTICO Y TRATAMIENTO DE LA HIPERTENSIÓN ARTERIAL \\nSISTÉMICA  \\n \\nDomicilio\\nUrgencias\\n(Atención médica \\ncontinua)\\nPaciente que acude a su primera consulta \\n(primaria/ 1° nivel)\\nVer GPC de HAS en \\nsituaciones especiales\\n¿Presión\\n> 140/90?\\nModificar estilos \\nde vida\\nNo\\nSeguimiento anual por \\nconsulta externa\\n¿Presión \\n> 180/90 o \\nDOB?\\nSi\\nIniciar tratamiento \\nfarmacológico\\nEnviar a especialista \\n(2° Nivel), conforme a \\ncriterios de referencia\\nModificar estilos \\nde vida\\nNo\\nProtocolo \\nestudio \\n2° Consulta \\n(al mes)\\n¿ > 140/90 o \\nBitacora (+)?\\nModificar estilos \\nde vida\\nSeguimiento anual por \\nconsulta externa\\nAtención \\nambulatoria\\nSiNo\\nSi\\n2\\n \\n \\n \\n5. Diagramas de Flujo\\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n22 \\n \\n \\n2\\nDar tratamiento de iniciocon \\nfármacos de primera línea\\n¿Hipertensión \\nArterial\\ncontrolada?\\nCambiar estilos de vida \\n(dieta, rutina de ejercicios)\\nContinuarcon estilo de \\nvida saludable y\\ntratamiento farmacológico \\nde 1 ó 2 línea\\nSeguimiento activo en \\natención primaria a la salud\\nCita a la consulta \\nexterna\\nAjustartratamiento: \\n1.  Incrementar dosis de \\nfármaco de inicio hasta la \\nmáxima tolerada\\n2. Agregar un 2 fármaco \\nNo\\n¿Hipertensión \\nArterial\\ncontrolada?\\nRevaloración semanal\\nNo\\nAjustartratamiento \\nfarmacológico: \\n1.  Incrementar dosis de \\nfármacos previos hasta la \\nmáxima tolerada\\n2. Agregar un 3 fármaco \\n¿Hipertensión \\nArterial\\ncontrolada?\\nNo\\nRevaloración semanal\\nSi\\nSi\\nContinuarcon estilo de \\nvida saludable y\\ntratamiento farmacológico \\nde 2 línea\\nCita a la consulta \\nexterna\\nReferencia a 2 Nivel de \\natención\\nSeguimiento activo en \\natención primaria a la salud\\nSi\\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n23 \\n \\n \\n \\nCUADRO VIII. MEDICAMENTOS PARA EL TRATAMIENTO DE HIPERTENSIÓN ARTERIAL SISTÉMICA, \\nSEGÚN LA CLASE Y PRINCIPIO ACTIVO \\n \\n \\nCLASE FÁRMACO \\nDiuréticos tiazídicos \\nClortalidona \\nHidoroclorotiazida \\nDiuréticos de asa \\nFurosemida \\nBloqueantes de los  receptores de \\naldosterona \\nEspironolactona \\nBeta-Bloqueadores \\nMetoprolol \\nPropanolol \\nIECA  \\n(Inhibodres de la enzima convertidora de \\nangiotensina) \\nCaptopril \\nEnalapril \\nARA II \\n(Antagonsitas de los receptores de \\nangiotensina II) \\nCandesartán \\nLosartán \\nTelmisartán \\nValsartán \\n \\nCalcio antagonistas \\nNo Dihidropiridinicos \\nDiltiazem  \\nVerapamilo \\nCalcio antagonistas \\nDihidropiridinicos \\nNifedipino \\nAmlodipino \\nFelodipino \\nAlfa-\\n1\\n Bloqueadores \\nPrazocina \\nAgonistas centrales alfa-\\n2 \\ny otros \\nfármacos de acción central. \\nMetildopa \\nVasodilatadores  \\nDirectos \\nHidralacina \\nFuente: JNC-8, 2013. \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n24 \\n \\n \\n \\nCUADRO IX.COMBINACIONES DE SEGUNDA LÍNEA PARA LOS RÉGIMES DE LOS TRATAMIENTOS DE \\nINICIO Y MANTENIMIENTO \\n \\n \\nInicio/Mantenimiento \\nDiuréticos \\ntiazidas \\nCa-\\nantagonista \\nIECA ARA II \\nDiuréticos tiazidas \\n CA CA CA \\nCa-antogonista \\nCA  CA CA \\nIECA \\nCA CA  CNR \\nARA II \\nCA CA CNR \\n \\nBeta-bloqueadores \\nCU CU CU \\nCU \\n \\nNota: Verde (CA): combinación aceptable; Amarillo: (CU): combinación útil, con limitaciones; Rojo (CNR): \\ncombinación no recomendable.  \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n25 \\n \\n \\nCUADRO X. TRATAMIENTO FARMACOLÓGICO PARA EL PACIENTES CON HAS CON O SIN \\nCONDICIONES ASOCIADAS. \\nCondición Meta Terapia primera  \\nlínea  \\nTerapia   segunda \\nlínea \\nObservaciones \\nSIN CONDICIONES ESPECIALES \\nHipertensión \\nHipertensión    arterial \\ndiastólica  con  o  sin \\nhipertensión   sistólica \\n>140/90 mm Hg \\n< 140/90  \\nmm Hg \\nDiuréticos de tiazidas,  \\nIECA o ARA II, CaA, BB \\n \\nConsiderar el inicio de la terapia \\ncon  combinaciones  de  fármacos \\nde  primera  línea  si  la  presión \\narterial sistólica es ≥20 mm Hg o \\npresión  arterial  diastólica ≥10 \\nmm Hg de la meta \\nCombinaciones   de \\nfármacos de primera \\nlínea \\nNo se recomienda monoterapia \\ncon  BB en  enfermos ≥60  años \\nde edad. \\n \\n \\nVigilar presencia de hipocalemia \\nHipertensión    arterial \\nsistólica aislada  \\n \\nDiuréticos Tiazidicos, ARA II, CaA Combinaciones   de \\nfármacos de primera \\nlínea \\n \\nCON CONDICIONES ESPECIALES \\nAdulto  mayor  con  HAS \\nsistólica   aislada   (en \\nausencia de insuficiencia \\ncardíaca) \\n \\n> 80 años: \\n<150   mm \\nHg \\nDiuréticos \\nCaA \\n Titular  dosis  de  diurético  y/o \\nCaA \\nNo se recomienda BB \\nDiabetes  mellitus  con \\nmicro     albuminuria, \\nenfermedad     renal, \\ncardiovascular  y  otros \\nfactores de riesgo \\n< 130/80  \\nmm Hg \\nIECA o  \\nARA II \\nCombinación    con \\nCaA  \\nConsiderar  un  diurético  de  Asa \\nen  enfermos  con  nefropatía  y \\nsobrecarga de volumen \\nDiabetes  mellitus  no \\nincluida  en  la  categoría \\nanterior \\nIECA o ARA II \\nCaA \\nDiuréticos tiazidicos \\nCombinación     de \\nIECA+CaA \\n \\nSíndrome metabólico < 140/90  \\nmm Hg \\nIECA o ARA II,  \\nCaA \\n  \\nEnfermedad \\ncardiovascular  \\nCoronariopatía \\n<140/90  \\nmm Hg \\nIECA o ARA II \\n \\nAgregue CaA  Evitar CaA como  nifedipina  y \\ncombinación de IECA con ARA II. \\nAngina estable BB \\nInfarto  del  miocardio \\nreciente \\nBB, IECA  (ARA  II  en  caso  de \\nintolerancia a IECA) \\nAgregue CaA, si el BB \\nestá contraindicado \\nCon  el  uso  de  BB,  vigilar los \\ndatos de falla cardíaca aguda. \\nInsuficiencia cardíaca Diuréticos  (asa  o  ahorrador  de \\npotasio), BB, IECA (ARA II en caso \\nde intolerancia a IECA) \\nIECA  con  hidralazina \\nsi  el  IECA  o  el  ARA \\nestán \\ncontraindicados. \\nTitular dosis de IECA o ARA II \\nHipertrofia   ventricular \\nizquierda \\nIECA o ARA II \\nCaA \\nDiuréticos de Tiazidas \\nCombinaciones   de \\nfármacos de primera \\nlínea \\n \\nInsuficiencia renal 130/80  \\nmm Hg \\nIECA o ARA II   \\nNefropatía  no  diabética \\ncon proteinuria \\n140/90  \\nmm Hg \\nIECA o ARA II, \\nDiuréticos  \\nCombinaciones   de \\nfármacos de primera \\nlínea \\nMonitoreo de la función renal y \\nde los niveles de potasio \\nNota: BB, Beta-Bloqueadores; IECA: Inhibidores de la Enzima Convertidora de Angiotensina; ARA II: \\nAntagonistas de Receptores de Angiotensina II; CaA: Calcio-Antagonista. \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n26 \\n \\n \\nCUADRO XI. \\nMedicamentos mencionados en la guía e indicados en el tratamiento de Hipertensión \\narterial sistémica del Cuadro Básico de IMSS y del Cuadro Básico Sectorial: \\n \\nCLAVE PRINCIPIO \\nACTIVO \\nDOSIS \\nRECOMENDADA \\nPRESENTACIÓN TIEMPO EFECTOS ADVERSOS \\n2301 Hidroclorotiazida 12.5 A 100mg/día Tabletas 25 mg Indefinido Anorexia nausea vómito dolor \\nabdominal  \\nhipokalemia \\n561 Cortalidona 25 a 50 mg/día Tabletas 50 mg Indefinido Hiponatremia \\nHipotasemia \\nHiperglucemia \\nHpercalcemia \\n574 Captopril 25 a 150 mg/día Tabletas 25 mg Indefinido Tos, proteinuria \\nDisgeusia \\nDiarrea  \\n2501 Enalapril 10 a 60 mg Tabletas 10 mg Indefinido Tos, proteinuria \\nDisgeusia \\nDiarrea \\n599 Nifedipino 30 a 60 mg Tabletas 30 mg Indefinido Edema    Rubor    Cefalea \\nTaquicardia \\n596 Verapamil 80 a 480 mg Tabletas 80 mg Indefinido Hipotensión     Bradicardia \\nNaúsea Rubor \\nConstipación Edema \\n530 Clorhidrato     de \\npropranolol \\n20 a 240 mg Tabletas de 10 y \\n40 mg \\nIndefinido Bradicardia,bronco \\nespasmo,constipación \\n572 Tartrato       de \\nmetoprolol \\n50 a 300 mg Tabletas 100 mg Indefinido Bradicardia,hipotensión \\ndiarrea,fatiga \\n573 Clorhidrato     de \\nprazocin \\n1 a 6 mg Tabletas de 1 y 2 \\nmg \\nIndefinido Hipotensión     ortostática \\nmareo síncope taquicardia \\n2520 Losartan potasico 50 a 200 mg Tabletas 50mg Indefinido Vertigo Hipotensión Rash \\n2114 Felodipino 5 a 10 mg Tabletas 5 mg Indefinido Edema    Rubor    Cefalea, \\nTaquicardia \\n4201 Hidralazina 50 a 100 mg Tabletas 10 y 50 \\nmg \\nIndefinido Hipotensión  Cefalea  Lupus \\nCefalea Taquicardia  \\n103 Ácido acetilsalicilico 150 mg/día Tabletas 300 mg  Indefinido Tinnitus   prolongación   de \\ntiempos   de   coagulación \\nhemorragia hepatitis asma \\n4246 Clopidogrel 75 mg /día Tabletas 75 mg Indefinido Neutropenia  trombocitopenia \\ndiarrea dispepsia \\n5105 Esmolol 50  a  100  mcg  / \\nKg/min \\nFco ámpula \\n250mg/ml \\n10ml \\nDosis \\nRespuesta \\nHipotension        naúsea \\nbroncoespasmo  \\n4114 Nitroglicerina 50 mg en 100 cc Frasco   ámpula \\n50 mg  \\nDosis  \\nrespuesta \\nCefalea        Hipotensión \\nTaquicardia \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n27 \\n \\n \\nCUADRO XII. CONTRAINDICACIONES PARA EL USO DE FÁRMACOS ANTIHIPERTENSIVOS. \\n \\nFÁRMACO ABSOLUTAS RELATIVAS \\nDiuréticos (Tiazidas) Gota Síndrome Metabólico \\nIntolerancia a la Glucosa \\nEmbarazo \\nHipercalcemia \\nHipocalcemia \\nIECA Embarazo \\nEdema angioneuóico  \\nHipercalemia \\nEstenosis renal bilateral  \\nMujer en edad fértil \\nARA II Embarazo \\nHipercalemia \\nEstenosis renal bilateral \\nMujer en edad fértil \\nCalcio        antagonistas \\n(Dihidropiridina) \\n Taquiarritmia \\nInsuficiencia cardíaca  \\nCalcio-antagonistas \\n(Verapamilo, diltiacem) \\nBloqueo  de  A–V    (grado  2  o  3,  bloqueo \\ntrifascicular),  \\nFalla grave del ventrículo izquierdo  \\nFalla cardiaca \\n \\nbeta-bloqueadores Asma \\nBloqueo A–V (Grado 2 o 3) \\nSíndrome Metabólico \\nIntolerancia a la Glucosa \\nAtletas y enfermos físicamente activos \\nEPOC  (excepto  para  vasodilatadores, \\nbeta-bloqueadores) \\nAntagonistas  de  receptores \\nde Mineralocorticoides \\nInsuficiencia  aguda  y renal  (TFG  <30 \\nmL/min)  \\nHypercalemia \\n \\n \\nIECA: Inhibidor de Enzima Convertidora de Angiotensina,  \\nARA II: Bloqueadores de Receptores de Angiotensina \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n28 \\n \\n \\nCUADRO XIII. INTERACCIONES FARMACOLOGICAS PARA EL PACIENTE ADULTO \\nJOVEN Y MAYOR \\n \\nClase   de   fármaco \\n/principio activo \\nFármaco interactuante Consecuencia Profilaxis \\nbeta-bloqueadores \\nEfectos: \\n \\nCalcio antagonista, especial \\natención con Nifedipino. \\n \\nRiesgo  de  isquemia \\nmiocárdica. \\nControl de tensión arterial, dosis \\najustada. \\nInteracciones \\nhemodinámicas \\nVerapamilo,  diltiazem.  La \\nmayoría de los anestésicos. \\n \\nRiesgo    de    falla \\ncardiaca, hipotensión. \\n \\nEscrutinio    de    insuficiencia \\ncardiaca, dosis ajustada. \\n \\nInteracciones \\nelectrofisiológicas \\n \\nVerapamilo, diltiazem. \\n \\nBradicardia,   Bloqueo \\ncompleto  de   rama, \\nhipotensión. \\n \\nDescartar  síndrome  de  seno \\nenfermo,  enfermedad  del  nodo \\nAV, Falla de VI. \\n \\n \\nAmiodarona \\n \\nBradicardia, bloqueo de \\nrama. \\n \\nDescartar enfermedad nodal. \\n \\nInteracciones hepáticas: \\n(Carvedilol,     labetalol, \\nmetoprolol,    propanolol, \\nprobablemente timolol). \\nInhibidores del   CYP2D6 \\nhepático;      cimetidina, \\nritonavir, quinidina. \\nEfectos beta-\\nbloqueadores \\nexcesivos \\nEvitar  la  interacción  o  reducir  la \\ndosis de beta-bloqueador. \\n \\nCalcioantagonistas \\nVerapamilo \\n \\nbeta-bloqueadores \\n \\nEfectos inotrópicos \\nnegativos y nodales. \\n \\nEvitar  la  interacción  o  reducir  la \\ndosis de beta bloqueador. \\n \\n \\nIntoxicación digitálica \\n \\nAsistolia,     bloqueo \\ncompleto de rama. \\nEvitar vía intravenosa. \\n \\n \\n \\n \\n \\nDigoxina \\n \\nRiesgo de toxicidad de \\ndigoxina. \\nRedosificar  digoxina y  muestreo \\nsanguíneo. \\n \\n Prazocin     y     otros \\nalfabloqueadores. \\n \\nHipotensión excesiva. \\n \\nVerificación de la tensión arterial \\nen el uso adyuvante. \\n \\n beta-bloqueadores \\n \\n \\nBradicardia \\n \\nVigilancia con electrocardiograma \\ny de la función ventricular. \\n \\nNifedipino \\n \\nPrazocin,    otros    alfa \\nbloqueadores. \\nEl  nifedipino  mejora  la \\npobre función del VI. \\nDisminuye  el  efecto  de  la \\nquinidina. \\nDiuréticos \\nTiazidicos y de Asa \\n \\nAINEs \\n \\nDisminuye  el  efecto \\nanti-hipertensivo. \\n \\nAjustar  la  dosis  del diurético o \\nadicionar otro agente. \\n IECAs, BRAs \\n \\nHipotensión excesiva, \\nuremia prerenal. \\n \\nDisminuir  la  dosis  de  diurético; \\niniciar dosificación baja. \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n29 \\n \\nFuente: adaptada CHEP, 2013\\n \\n \\n \\nCaptopril \\n \\nPerdida  de  la  eficacia \\ndiurética         de \\nfurosemida. \\nCambiar a otro IECA. \\n \\n \\n \\n \\n \\nDiurético de Asa \\n \\nAspirina \\n \\nAsumir  menor  eficacia \\nen la falla cardiaca. \\n \\nSuspender  la  aspirina  al inicio \\nagudo  del  tratamiento  de  falla \\ncardiaca. \\nDiurético   ahorrador   de \\npotasio. \\n \\nIECA, ARA II \\n \\nHipercalemia. \\n \\nMonitorear  potasio  y  reducir  la \\ndosis de IECA. \\nAntagonista  del  receptor \\nde aldosterona. \\nEplerenona \\nIECA Hipercalemia. Monitorear  potasio  y  reducir  o \\neliminar IECA, BRA o el diurético \\nahorrador de potasio. \\n \\nIECA  \\n \\n \\nDiuréticos  excesivos,  raro \\nen hipertensión. \\n \\nRiesgo de falla renal. \\n \\nReducir  la  dosis  de  diurético, \\ncorregir el volumen depletado. \\n \\n Diuréticos  ahorradores  de \\npotasio, espironolactona. \\nHipercalemia \\n \\nEvitar la combinación o usar con \\nprecaución. \\n \\n AINEs Disminuye la TA. Evitarlo en lo posible \\n Aspirina \\n \\nDisminuye  efectos  de \\nla falla cardiaca. \\nDisminuir la dosis. \\n \\n Diurético de Asa \\n \\nDisminuye  el efecto \\ndiurético        de \\nfurosemida. \\nConsiderar un IECA alternativo. \\n \\nCaptopril \\n \\nFármacos \\ninmunosupresores \\nAumenta  el  riesgo  de \\nneutropenia. \\nEvitar  la  combinación,  vigilancia \\nde neutrófilos. \\nARA II \\n \\nExceso  de  diuréticos,  raro \\nen hipertensión. \\nHipotensión  al iniciarel \\ntratamiento,  riesgo  de \\nlesión renal. \\nReducir  la  dosis  de  diurético, \\ncorregir la depleción de volumen. \\n \\nARA II \\nVasodilatadores \\n \\nbeta-bloqueadores \\nmetabolizados en hígado \\n \\nDisminuye        el \\nmetabolismo      de \\nbetabloqueadores y \\naumenta  los  niveles \\nséricos. \\nDisminuir la dosis de metoprolol. \\n \\n Nitratos \\n \\nMenor  tolerancia  a \\nnifedipino,  riesgo  de \\nhipotension excesiva \\nDosificar lentamente. \\n \\nHidralazina Verapamilo \\n \\nSinergia  con  efecto \\nantihipertensivo \\nAjustar dosis. \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n30 \\n \\n \\n \\nDurango 289- 1A Colonia Roma \\nDelegación Cuauhtémoc, 06700 México, DF. \\nPágina Web: www.imss.gob.mx \\n \\nPublicado por Intituto Mexicano del Seguro Social \\n© Copyright IMSS “Derechos Reservados”. Ley Federal de Derecho de Autor \\n \\nEditor General \\nCoordinación Técnica de Excelencia Clínica \\nCoordinación de Unidades Médicas de Alta Especialidad \\n2014 \\n \\nISBN: 978-607-7790-12-9"}'::jsonb, false, 16693, '2026-11-25 23:45:33.224+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '718-18'), 'GER', '{"alarmas": "Referir a segundo nivel: pacientes con hiperglucemia severa (glucosa >300 mg/dL), síntomas de hiperglucemia grave o cetoacidosis, hipoglucemia severa no controlable, complicaciones agudas (infecciones, insuficiencia renal avanzada), embarazo, condiciones que alteren pruebas diagnósticas (p. ej. hemoglobinopatías) y pacientes que requieran manejo insulinoterápico complejo o terapia intensiva.", "prevencion": "Educación sobre factores de riesgo, enfatizando actividad física diaria ≥30 minutos, dieta mediterránea baja en grasas saturadas y rica en fibra, mantener peso corporal con IMC <25, evitar tabaquismo. Realizar tamizaje con FINDRISC cada 1 a 3 años según riesgo. En personas con prediabetes (glucosa en ayunas 100-125 mg/dL o HbA1c 5.7-6.4%), promover intensificación de cambios en estilo de vida para retrasar o prevenir desarrollo de diabetes.", "diagnostico": "Usar cuestionario FINDRISC para tamizaje de DM2 en adultos con factores de riesgo, puntaje >9 y glucosa en ayuno >100 mg/dL indican alto riesgo. Confirmar diagnóstico con HbA1c ≥6.5% en laboratorio certificado; si glucosa en ayunas entre 100-125 mg/dL, puede usarse prueba de tolerancia oral con carga de 75 g, valor diagnóstico >200 mg/dL a las 2 horas. Evitar uso de HbA1c en embarazo, hemodiálisis, transfusiones recientes o enfermedades de la sangre que alteren glóbulos rojos.", "seguimiento": "Control trimestral con evaluación clínica y medición de HbA1c para verificar metas (<7%), control de glucosa capilar preprandial (80-130 mg/dL) y postprandial (<180 mg/dL). Revisar adherencia, signos de hipoglucemia, cambios en estilo de vida y descartar infecciones. Reevaluar dosis y esquema farmacológico basándose en glucemias capilares y HbA1c. Monitoreo anual de función renal y albuminuria en pacientes con DM2, iniciar IECA o ARA II en caso de microalbuminuria aún sin hipertensión.", "tratamiento": "Iniciar metformina oral 850 mg dos veces al día junto con cambios intensivos en estilo de vida (dieta mediterránea y actividad física diaria de al menos 30 minutos) en DM2 recién diagnosticados, aún si HbA1c está cerca de 7%. Si HbA1c >8%, añadir inhibidor DPP-4 como primer paso. Si DPP-4 contraindicado o no disponible, considerar sulfonilureas de bajo riesgo (glimepirida o glicazida), evitando glibenclamida. No iniciar SGLT-2 como primera combinación. En terapia dual que no alcance metas, añadir tercer fármaco: insulina basal si no hay obesidad, o agonista GLP-1 si hay obesidad (IMC ≥30). Dosis Insulina NPH iniciar 10 UI o 0.2 UI/kg por noche; ajustar cada 3 días incrementando 2-4 UI según glucosa en ayuno. Monitorizar y ajustar según algoritmo."}'::jsonb, false, 40299, '2026-11-25 23:42:36.889+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '718-18'), 'GRR', E'{"alarmas": "Glucosa capilar preprandial >300 mg/dL con síntomas, hiperglucemia grave, hipoglucemias recurrentes, signos de infección o complicaciones agudas, insuficiencia renal severa (creatinina <30 ml/min). Requieren referencia urgente a segundo nivel.", "prevencion": "Consejería breve sobre riesgos de diabetes y beneficios de estilo de vida saludable: aumentar actividad física diaria ≥30 min, pérdida y mantenimiento de peso, dieta rica en fibra y baja en grasas saturadas, especialmente dieta mediterránea. Realizar tamizaje con FINDRISC cada 3 a 5 años según nivel de riesgo. Promover seguimiento periódico para detectar precozmente prediabetes y diabetes.", "diagnostico": "Usar cuestionario FINDRISC para tamizaje de riesgo en adultos 40-74 años. Confirmar diagnóstico con HbA1c ≥6.5% en pacientes con glucosa en ayunas 100-125 mg/dL o glucosa plasmática en ayunas ≥126 mg/dL. Alternativa: prueba de tolerancia oral con glucosa ≥200 mg/dL a las 2 horas. No usar HbA1c en embarazo, hemodiálisis o hemoglobinopatías.", "seguimiento": "Control trimestral de HbA1c y glucosa capilar. Evaluar apego, síntomas hipoglucemia, historial glucemias y ausencia de infecciones. Ajustar tratamiento farmacológico y refuerzo de cambios en estilo de vida según metas: HbA1c <7%, glucosa preprandial 80-130 mg/dL, postprandial <180 mg/dL. Reevaluar riesgo anual en casos de prediabetes.", "tratamiento": "Iniciar metformina 850 mg hasta 3 veces al día junto con cambios intensivos en estilo de vida (dieta mediterránea, actividad física ≥30 min/día). Si HbA1c 8-8.5%, agregar segundo antidiabético: preferentemente inhibidor DPP-4 (sitagliptina 100 mg VO diario) o pioglitazona 15-45 mg VO diario con precaución. Evitar sulfonilureas inicialmente por riesgo hipoglucemia, salvo si DPP-4/SGLT2 no son opción; dosis glibenclamida 5-15 mg/día en 2 tomas. HbA1c >9% o glucosa >300 mg/dL sintomáticos, iniciar insulina NPH 10 U o 0.2 U/kg nocturna, titrar 2-4 U c/3 días según glucosa en ayuno (meta 80-130 mg/dL).", "texto_completo": "GUÍA DE PRÁCTICA CLÍNICA GPC\\n \\n \\n \\n \\n                                                                                                                   \\n \\n \\nDiagnóstico y Tratamiento \\nFarmacológico de la\\nDIABETES MELLITUS TIPO 2 EN \\nEL \\nPRIMER NIVEL DE ATENCIÓN\\n \\nGuía de Referencia Rápida\\nCatálogo Maestro de Guías de Práctica Clínica: gpc-iMSS-718-18\\nActualización \\n2018 \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de \\nAtención  \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nDurango 289- 1A Colonia Roma \\nDelegación Cuauhtémoc, 06700 México, DF. \\nPágina Web: www.imss.gob.mx\\n \\n \\nPublicado por Instituto Mexicano del Seguro Social \\n© Copyright Instituto Mexicano del Seguro Social “Derechos Reservados”. Ley Federal de Derecho de Autor \\n \\nEditor General \\nCoordinación Técnica de Excelencia Clínica \\nCoordinación de Unidades Médicas de Alta Especialidad \\n \\nLa  guía  de  referencia  rápida  tiene  como  objetivo  proporcionar  al  usuario  las  recomendaciones  clave  de  la  guía  \\nDiagnóstico  y Tratamiento  Farmacológico  de  la  Diabetes  Mellitus  Tipo  2  en  el  Primer  Nivel  de  Atención, \\nseleccionadas  con  base  a  su  impacto  en  salud  por  el  grupo  desarrollador,  las  cuales  pueden  variar  en  función  de  la  \\nintervención de que se trate, así como del contexto regional o local en el ámbito de su aplicación. \\n \\nPara mayor información, se sugiere consultar la guía en su versión extensa de “Evidencias y Recomendaciones” en el \\nCatálogo Maestro de Guías de Práctica Clínica, la cual puede ser descargada de Internet en:  \\n \\nhttp://imss.gob.mx/profesionales-salud/gpc \\n \\nDebe  ser  citado  como:  Diagnóstico  y Tratamiento  Farmacológico  de  la  Diabetes  Mellitus  Tipo  2  en  el  Primer  \\nNivel  de  Atención.  Guía  de  Rerencia  Rápida:  Guía  de  Práctica  Clínica.  México,  Instituto  Mexicano  del  Seguro  Social;  \\n2018  \\nDisponible en: http://imss.gob.mx/profesionales-salud/gpc \\n \\nISBN en trámite \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n1. Diagramas de Flujo \\nAlgoritmo 1. Identificación y manejo del riesgo en Diabetes Mellitus Tipo 2 \\nIdentificación y manejo de riesgo en Diabetes \\nMellitus Tipo 2\\nScore de riesgo \\nintermedio o bajo \\nScore de alto riesgo\\nConsiderar examen de sangre para personas \\ndel sur de Asia y de China > 25 años y con un \\nIMC >23 kg/m2\\nOfrecer consejería breve \\nrespecto a:\\nLos riesgos de desarrollar \\ndiabetes\\nLos beneficios de un estilo de \\nvida saludable\\nLa modificación de factores de \\nriesgo\\nRealizar un examen de sangre\\nEscoger entre glucosa plasmática en \\nayunas o HbA1c\\nRiesgo Moderado\\nGPA <100 mg/dL o \\nHbA1c < 6%\\nRiesgo Alto\\nGPA 100 a 125 mg/\\ndL o HbA1c 6 a 6.4%\\nDiabetes Tipo 2 probable\\nGPA >126 mg/dL ó HbA1c \\n>6.5%\\nOfrecer consejería \\nbreve para:\\nDiscutir los riesgos de \\ndesarrollar diabetes\\nAyudar a modificar \\nfactores de riesgo \\nindividuales\\nOfrecer servicios de \\napoyo adaptados\\nOfrecer programa \\nintensivo de cambios en \\nestilo de vida para:\\nIncrementar actividad física\\nLograr y mantener pérdida \\nde peso\\nIncrementar fibra en dieta, \\nreducir ingesta de grasa, \\nparticularmente saturadas\\nRealizar examen de \\nsangre si se encuentra \\nasintomático, para \\nconfirmar o rechazar la \\npresencia de diabetes\\nSí se confirma\\nIngresa a algoritmo de \\nmanejo de diabetes\\nNo se confirma\\nOfrecer programa intensivo \\nde cambios en estilo de \\nvida\\nReevaluar peso e IMC y \\nofrecer examen de sangre al \\nmenos una vez al año \\nReevaluar riesgo al \\nmenos cada 3 años\\nReevaluar riesgo al \\nmenos cada 5 años\\n40-74 años\\nUsar herramienta de evaluación del \\nriesgo validada o cuestionario de \\nautoevaluación validado\\n>75 años\\nUsar herramientas de \\nevaluación de riesgos y \\ncuestionarios\\nGrupos de alto riesgo\\nAfrocaribeños, africanos, hispanos/\\nlatinos, personas del sur de Asia, etc.\\nPacientes con condiciones que \\nincrementan el riesgo de padecer DM tipo \\n2.\\nUtilizar herramientas de evaluación de \\nriesgos y cuestionarios.\\n \\n \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\nAlgoritmo 2. Tratamiento Farmacológico de pacientes con Diabetes Mellitus Tipo 2 \\n \\nDx reciente DM tipo 2\\nConsulta nutricional \\nCambio intensivo estilo de vida \\nUso de metformina \\nHbA1c <7.9%\\nHbA1c 8 - 8.5%%\\nHbA1c >9%\\nó\\nGlucosa >300mg/dl y \\nsintomatología\\nTerapia dual\\n- Glibenclamida 5mg máx 15mg/dl dividido \\n2 tomas ó\\n-Pioglitazona 15mg c/24hrs, máximo \\n45mg/día (precaución en ICC/edema) ó\\n-Sitaglipina 100mg c/24hrs (máx)\\nDep. Creatinina 30-40  50mgc/24hrs (máx)\\nMantener monoterapia\\n-Metformina 850mg hasta c/8hrs \\n-Considerar Sitaglipina en caso de \\nintolerancia o contraindicación para \\nmetformina (insuf. Hepatica) \\nDep. Creatinina <30ml, alergia \\nCumple Glicemia \\nrecomendada\\nSeguimiento \\ntrimestral \\nEvaluación \\nclínica \\nInestable\\nEstable \\nHbA1c 8.6 - 8.9%\\nTerapia triple\\n* si el paciente acepta considerar terapia \\ncon  insulina\\n+pioglitazona+sitagliptina \\n-Metformina+glibenclamida+pioglitazona\\n+glibenclamida+sitagliptina\\n+glibenclamida+insulina\\n+pioglitazona+insulina\\nCumple Glicemia \\nrecomendada \\nSe puede ajustar dosis o esquema de tratamiento de acuerdo a requerimientos del paciente \\nNO\\nIniciar Insulina NPH\\nMetformina y dosis inicial:\\nA) Insulina NPH 10UI \\nO\\nB)Insulina NPH 0.2 x peso Kg\\n*Ver anexo para cálculo de dosis inicial, \\nrequerimiento diario y titulación. \\nVer Terapia triple\\nó\\nVer Insulina \\nSI\\nCumple Glicemia \\nrecomendada\\nVer Terapia \\ndoble\\nSI\\nNO\\nNO\\nSI\\nMetas cumplidas\\n-Reforzar cambios en \\netilo de vida \\n-Revisión trimestral  \\nMetas de control:\\nHBa1 <7 %\\nGlucosa capilar preprandial: \\n80-130mg/dl \\nGlucosa capilar postprandial: \\n<180mg/dl \\nMetas no cumplidas\\nRealizar esta lista de \\nverificación para escalar \\nel tratamiento.  \\nLista de verificación\\n1. Valorar bitácora de glucosa capilar\\n2. Búsqueda intencionada de síntomas de hipoglucemia \\n3.  Valorar apego al tratamiento  y cambios en el estilo de vida \\n4. Descartar infecciones agudas \\n  \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\nAlgoritmo 3. Inicio y ajuste de insulina en Diabetes Mellitus Tipo 2 \\n \\nInicio y Ajuste de regimen de Insulina en Diabetes Mellitus Tipo 2\\nIniciar con insulina de acción intermedia por las noches o a la \\nhora de acostarse o insulina de larga duración por las mañanas, \\nSe puede iniciar con 10 U o 0.2 U por kg\\nChecar glucosa en ayuno diario e incrementar dosis, usualmente 2 U cada 3 \\ndíashasta que los niveles en ayuno se encuentren dentro del rango deseado \\n(80 a 130 mg/dL); se puede ir aumentando la dosiscada vez más, por \\nejemplo, 4 U cada 3 días, si la glucosa en ayuno es > 180 mg/dL\\nSi ocurre hipoglucemia, o los niveles de \\nglucosa en ayuno son < 80 mg/dL, se debe \\nreducir la dosis al acostarse 4 U o 10%(la \\nque sea mayor)\\nSi la glucosa en ayuno se encuentra dentro del rango (80 a 130 mg/dL), se debe revisar la \\nglucosa antes del almuerzo, en la cena y al acostarse; dependiendo de los resultados de \\nglucosa, se añadirá una segunda inyección; se puede iniciar con 4 U y añadir 2 U cada 3 \\ndíashasta que la glucosa se encuentre en rango\\nGlucosa pre almuerzo\\nfuera de rango, añadir \\ninsulina de acción \\nrápidaen el desayuno\\nGlucosa pre cenafuera de \\nrango, añadir insulina NPH\\nen el desayuno o insulina de \\nacción rápida en el almuerzo\\nGlucosa antes de \\nacostarsefuera de rango, \\nañadir insulina de acción \\nrápidaen la cena\\n¿A1c >7% después \\nde 3 meses?\\nSI\\n¿A1c >7% \\ndespués de 3 \\nmeses?\\nSI\\nNO\\nContinuar régimen, checar A1c cada 3 \\nmeses\\nReevaluar glucosa antes de las comidas y si está\\nfuera de rango, se puedeañadir otra inyección; si \\nA1c continúa fuera de rango, evaluar niveles \\nposprandiales a las 2 horas y ajustar insulina de \\nacción rápida preprandial\\nNO\\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n \\n2. <Intervención en Salud> \\n \\nTAMIZAJE \\n \\nRecomendación Clave \\nGR* \\nSe recomienda utilizar el cuestionario FINDRISC como herramienta de tamizaje para \\nla detección de riesgo de Diabetes, sobre todo en pacientes con múltiples factores de \\nriesgo. \\nB \\nEl  test  FINDRISC  es  una  herramienta  útil  para  detectar  pacientes  con  alto  riesgo  de  \\ndesarrollar  Diabetes,  sobre  todo  en  aquellos  con  un  puntaje  >9  y  una  glucosa  en  \\nayuno > 100 mg/dL. \\nB \\n \\nDIAGNÓSTICO \\n \\nRecomendación Clave \\nGR* \\nSe  recomienda  utilizar  la  HbA1c  para  confirmar  el  diagnóstico  de  Diabetes  Mellitus  \\nen  pacientes  que  dieron  positivo  en  alguna  prueba  de  tamizaje  y  que  presenten  una  \\nglucemia plasmática en ayunas entre 100 y 125 mg/dL. Un valor > 6.5% confirma el \\ndiagnóstico. \\nA \\nSe recomienda usar la curva de tolerancia a la glucosa oral en pacientes con glucemia \\nplasmática  en  ayunas  entre  100  y  125  mg/dL  y  que  muestren  preferencia  por  ésta  \\nprueba. Un valor > 200 mg/dL a las 2 horas de ingerir una carga de 75 g de glucosa \\nconfirma el diagnóstico. \\nA \\nUnicamente  se  deberán  utilizar  criterios  de  glucosa  plasmática  y  no  de  HbA1c  en  \\ncondiciones  que  incrementen  el  recambio  de glóbulos rojos, como el embarazo (en \\nsegundo  y  tercer  trimestre),  hemodiálisis,  transfusiones  recientes,  tratamiento  con  \\neritropoyetina, enfermedad de células falsiformes, etc. \\nD \\n \\nTRATAMIENTO \\n \\nRecomendación Clave \\nGR* \\nSe  recomienda  iniciar  tratamiento  farmacológico  con  Metformina  y  cambios  en  el  \\nestilo  de  vida  en  pacientes  con  DM2  recién  diagnosticada,  aunque  el  valor  inicial  de  \\nHbA1C esté cerca del valor óptimo. \\nFuerte a \\nfavor \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\nSe recomienda mantener un nivel alto de actividad  física  para  disminuír  el  riesgo  de  \\nmortalidad en pacientes adultos con Diabetes Mellitus tipo 2. \\nA \\nSe recomienda que los pacientes adultos con DM 2 recién diagnosticada se apeguen \\na la dieta mediterránea. \\nA \\nSe recomienda iniciar terapia combinada con metformina y otro antidiabético oral en \\npacientes adultos con DM tipo 2 recién diagnosticada y un nivel de HbA1c >8%. \\nA \\nNo se recomienda iniciar terapia combinada con sulfonilureas como la glibenclamida \\npor el riesgo de hipoglicemia; se sugiere considerar primero otros medicamentos. \\nA \\nNo  se  recomienda  iniciar  terapia  combinada  con  inhibidores  SGLT-2  en  pacientes  \\nadultos  con  diagnóstico  reciente  de  DM  tipo  2,  a  pesar  de  que  favorecen  la  pérdida  \\nde peso; únicamente se utilizarán como una alternativa en caso de que no se puedan \\nutilizar inhibidores DPP-4. \\nA \\nEn pacientes con diagnóstico reciente de Diabetes Mellitus tipo 2 que no alcanzan su \\nmeta  terapéutica  o  no  logran  mantenerla  con  metformina  como  monoterapia,  se  \\nrecomienda  como  primer  paso  agregar  un  inhibidor  DPP-4,  por  su  mejor  balance  \\nriesgo-beneficio. \\nFuerte     a     \\nfavor \\nEn pacientes con diabetes mellitus tipo 2 que no alcanzaron su meta terapéutica o no \\nlogran  mantenerla  con  metformina  como  monoterapia,  se  sugiere  agregar  una  \\nsulfonilurea  con    bajo  riesgo  de  hipoglucemia  (glimepirida,  glicazida)  cuando  los  \\ninhibidores DPP-4 O SGLT2  no están disponibles o se encuentran contraindicados. \\nDébil a \\nfavor \\nSe sugiere añadir como tercer fármaco la insulina basal en aquellos pacientes adultos \\ncon DM tipo 2 que no han alcanzado las metas de control de HbA1c o la han perdido \\ny no tienen obesidad. \\nA \\nSe  recomienda  añadir  como  tercer  fármaco  un  agonista  del  receptor  GLP-1  en  \\naquellos  pacientes  con  DM  tipo  2  que  no  logran  alcanzar  la  meta  de  HbA1c  con  \\nterapia combinada (dos fármacos) o la perdieron y no son obesos. \\nA \\nSe recomienda dar tratamiento con  IECA o ARA II en pacientes adultos con DM tipo \\n2   cuando   se   detecte   microlbuminuria   persistente   aunque   todavía   no   tengan   \\nhipertensión arterial. \\nA \\n \\n*Grado de Recomendación \\n \\n \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n3. CUADROS O FIGURAS \\n \\nCuadro 1. Escala FINDRISC \\n \\nLa  escala  FINDRISC  es  un  instrumento  de  cribaje  inicialmente  diseñado  para  valorar  el  riesgo  \\nindividual de desarrollar DM2 en el plazo de 10 años. \\nLas principales variables que se relacionan con el riesgo de desarrollar DM en esta escala son: edad, \\nIMC,   el   perímetro   de   la   cintura,   hipertensión   arterial   con   tratamiento   farmacológico   y   los   \\nantecedentes personales de glucemia elevada. \\n \\nCada respuesta tiene asignada una puntuación, variando la puntuación final entre 0 y 26. \\n \\nEdad Puntos \\nMenos de 45 años 0 puntos \\nEntre 45-54 años 2 puntos \\nEntre 55-64 años 3 puntos \\nMás de 64 años 4 puntos \\n \\nIMC (kg/m2) Puntos \\nMenos de 25 kg/m2    0 puntos \\nEntre 25/30 kg/m2 1 punto \\nMás de 30 kg/m2 3 puntos \\n \\nPerímetro abdominal \\nHombres                  Mujeres                  Puntos                  \\nMenos de 94 cm Menos de 80 cm     0 puntos \\nEntre 94-102 cm Entre 80-88 cm 3 puntos \\nMás de 102 cm Más de 88 cm 4 puntos \\n \\n¿Realiza normalmente al menos 30 minutos diarios de actividad física? \\nSi                                                                                       0                                                                                       puntos                                                                                       \\nNo  2 puntos \\n \\n¿Con qué frecuencia come frutas, verduras y hortalizas? \\nA diario 0 puntos \\nNo a diario 1 puntos \\n \\n¿Le han recetado alguna vez medicamentos contra la Hipertensión arterial? \\nSi                                                                                       2                                                                                       puntos                                                                                       \\nNo  0 puntos \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n¿Le han detectado alguna vez niveles altos de glucosa en sangre? \\nSi                                                                                       5                                                                                       puntos                                                                                       \\nNo  0 puntos \\n \\n¿Ha habido algún diagnóstico de DM en su familia? \\nNo                                                                                     0                                                                                     puntos                                                                                     \\nSí: abuelos, tíos o primos \\nhermanos (pero no padres, \\nhermanos o hijos) \\n3 puntos \\nSí: padres, hermanos o hijos 5 puntos \\n \\nPuntuación total \\n \\n  \\n \\nPuntuación total Riesgo de desarrollar diabetes en \\nlos próximos10 años \\nInterpretación \\nMenos de 7 puntos 1% Nivel de riesgo bajo \\nDe 7 a 11 puntos 4% Nivel de riesgo ligeramente \\nelevado \\nDe 12 a 14 puntos 17% Nivel de riesgo moderado \\nDe 15 a 20 puntos 33% Nivel de riesgo alto \\nMás de 20 puntos 50% Nivel de riesgo muy alto \\n \\nFuente:  Lindström  J,  Tuomilehto  J.  The  diabetes  risk  score:  a  practical  tool  to  predict  type  2  \\ndiabetes risk. Diabetes Care 2003;26(3):725-31. \\n \\nCuadro 2. Criterios para el diagnóstico de Diabetes ADA 2018 \\n \\nGlucosa plasmática en ayuno ≥ 126 mg/dL (7.0 mmol/L) (Ayuno definido como no haber tenido \\ningesta calórica en las últimas 8 horas). \\no \\nGlucosa plasmática a las 2 horas de ≥200 mg/dL (11.1 mmol/L) durante una prueba oral de \\ntolerancia a la glucosa. La prueba deberá ser realizada con una carga de 75 gramos \\nde glucosa disuelta en agua. \\no \\nHemoglobina   glucosilada   (A1C)   ≥   6.5%.   (48   mmol/mol)   Esta   prueba   debe   realizarse   en   \\nlaboratorios certificados de acuerdo a los estándares A1C del DCCT. \\no \\nPaciente con síntomas clásicos de hiperglicemia o crisis hiperglucémica con una \\nglucosa al azar ≥ 200 mg/dL. \\n \\nFuente: American Diabetes Association. Glycemic Targets: Standards of Medical Care in Diabetes-\\n2018. Diabetes Care. 2018 Jan;41(Suppl 1):S55-S64. \\n \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n \\n \\nCuadro 3. Criterios diagnóstico para Pre-Diabetes 2018 ADA 2018 \\n \\nGlucosa en ayuno 100 a 125 mg/dL \\no \\nGlucosa plasmática a las 2 horas 140 a 199 mg/dL duranta una prueba oral de tolerancia a la \\nglucosa. La prueba debe ser realizada con una carga de 75 g de glucosa disuelta en agua \\no \\nHemoglobina glucosilada (A1C) 5.7 a 6.4% \\n \\nFuente: American Diabetes Association. Glycemic Targets: Standards of Medical Care in Diabetes-\\n2018. Diabetes Care. 2018 Jan;41(Suppl 1):S55-S64. \\n \\nCuadro 4. Ventajas y desventajas de las pruebas diagnósticas para diabetes \\n \\nParámetro Ventajas Desventajas \\nGlucosa      oral      en      \\nayuno \\nEstándar establecido Muestra no estable \\n Rápido y fácil Variabilidad alta en el día a día \\nMuestra única Inconveniente (ayuno) \\nPredice complicaciones \\nmicrovasculares \\nRefleja la homestasis de la glucosa en un único \\npunto en el tiempo \\n   \\nPrueba                     de                     \\ntolerancia  oral  a  la  \\nglucosa   con   carga   \\nde       75       g       con       \\nmedición                 de                 \\nglucosa   en   plasma   \\na las 2 horas \\nEstándar establecido Muestra no estable \\n                                             Predice                                             complicaciones                                             \\nmicrovasculares \\nVariabilidad alta en el día a día \\n                                                       Inconveniente                                                       \\nDesagradable \\nCostosa \\n   \\nHemoglobina A1c \\nConveniente (se puede \\nhacer la medición en \\ncualquier momento del \\ndía) \\nCostosa \\n                                                 Una                                                 única                                                 muestra                                                 Engañosa en presencia de algunas \\nenfermedades (Ej. Hemoglobinopatías, \\ndeficiencia de hierro, anemia hemolítica, \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\nenfermedad renal o hepática severas) \\nPredice complicaciones \\nmicrovasculares \\nSe puede ver alterada por edad o raza \\nMejor predictor de \\nenfermedad \\ncardiovascular que la \\nglucosa oral en ayuno o \\nla prueba de tolerancia \\na glucosa oral a las 2 \\nhoras \\nSe requiere un ensayo validado y \\nestandarizado \\nVariabilidad baja en el \\ndía a día \\nNo se debe utilizar para diagnóstico en niños y \\nadolescentes, ni en pacientes con fibrosis \\nquística ni con sospecha de diabetes tipo 1, ni \\nen mujeres embarazadas en el tamizaje de \\nrutina para diabetes gestacional. \\nRefleja la concentración \\nde glucosa a largo plazo\\n \\n \\nFuente: Adaptado de Sacks DB. A1C versus glucose testing: A comparison. Diabetes Care 2011 \\nFeb; 34(2):518–23. \\n \\nCuadro 5. Fármacos insulino secretores: \\n \\nDosis y Potencia de Acción de las Sulfonilureas \\nFármaco Presentación tabletas Dosis diaria (mg) Potencia \\nTolbutamida                                       500                                       1000-2000                                       ++                                       \\nClorpropamida                                   250                                   250-500                                   ++++                                   \\nGlibenclamida                                       5                                       5-20                                       ++++                                       \\nGliclazida                                  80                                  160-240                                  ++                                  \\nGlipizida                                                 5                                                 5-20                                                 +++                                                 \\nGlimepirida 2 y 4 2-8 ++++ \\n \\nDosis de las Meglitinidas \\nFármaco Dosis tableta (mg) Dosis diaria (mg) \\nRepaglinida 0.5 – 1 - 2 1.5 a 12 \\nNateglinida 120 60 a 360 \\n \\nAnálogos del GLP 1 \\nFármaco Presentación inyectable Dosis diaria \\nExenatide 5 - 10 10 c/12 hr \\n \\nInhibidores de la DPP-4 (Gliptinas) \\nFármaco Presentación tabletas (mg) Dosis diaria (mg) \\nSitagliptina                                                                100                                                                100                                                                \\nVildagliptina                                                                50                                                                50-100                                                                \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n \\nCuadro 6. Fármacos insulino-sensibilizadores: \\n \\nFármaco Presentación tabletas (mg) Dosis diaria (mg) \\nMetformina 500, 850, 1000 500-2550 \\nMetformina acción prolongada 500, 750, 1000 500-2550 \\n \\nCuadro 7. Tiazolidinedionas (glitazonas): \\n \\nFármaco Dosis tabletas (mg) Dosis diaria (mg) \\nRosiglitazona 4 - 8 8 \\nPioglitazona                                                            15-30                                                            45                                                            \\n \\nCuadro  8:  Inhibidores  de  la  absorción  intestinal  de  monosacáridos  (inhibidores  de  alfa  \\nglucosidasas intestinales) \\n \\nFármaco Presentación tabletas (mg) Dosis diaria (mg) \\nAcarbosa 50 y 100 50-300 \\n \\nFuente:  Gobierno  de  Chile.  Ministerio  de  Salud.  Guía  Clínica  Diabetes  Mellitus  Tipo  2.  Serie  Guías  \\nClínicas Minsal. Santiago, Minsal, 2010."}'::jsonb, false, 6615, '2026-11-25 23:43:12.435+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
